/** A page contains live DOM controls; the book decoration is the same for all folios.
 * Character-only navigation never belongs to World, Combat, Skills or Library.
 * Keep ordinary page contents in document order. Do not manufacture rule values.
 */
function folioHTMLNodes(html){
 const template=document.createElement('template');template.innerHTML=html;
 return [...template.content.children];
}
function folioWeight(element){
 const n=(element.textContent||'').length;
 return 2+Math.min(200,n/105)+element.querySelectorAll('form,fieldset').length*7+
  element.querySelectorAll('tr').length*1.8+element.querySelectorAll('input,select,button,textarea').length*.9;
}
function folioBalancedParts(elements){
 if(elements.length<2)return [elements.map(x=>x.outerHTML).join(''),''];
 const weights=elements.map(folioWeight),total=weights.reduce((a,b)=>a+b,0);
 let balance=Infinity,split=Math.max(1,Math.floor(elements.length/2)),sum=0;
 for(let i=1;i<elements.length;i++){
  sum+=weights[i-1];const diff=Math.abs(total-2*sum);
  if(diff<balance){balance=diff;split=i;}
 }
 return [elements.slice(0,split).map(x=>x.outerHTML).join(''),elements.slice(split).map(x=>x.outerHTML).join('')];
}
/** Render the full original library record as a compact manuscript entry.
 * Form fields and data attributes remain actual DOM; purchase/edit handlers are unchanged.
 */
function folioLibraryEntry(row,headers){
 const cells=[...row.children];
 if(!cells.length)return '';
 const fields=cells.slice(1,-2).map((cell,i)=>{const label=headers[i+1]||'Parametr',help=libraryFieldHelp(label);return `<div class="folio-catalog-field"><dt class="catalog-parameter-tip" tabindex="0" data-hmk-help="${esc(help)}">${esc(label)}</dt><dd class="catalog-parameter-tip" tabindex="0" data-hmk-help="${esc(help)}">${cell.innerHTML}</dd></div>`;}).join('');
 const identity=[...row.attributes].filter(a=>a.name.startsWith('data-')).map(a=>` ${a.name}="${esc(a.value)}"`).join('');
 return `<article class="folio-catalog-entry"${identity}><div class="folio-catalog-heading" tabindex="0" title="${esc(cells[0].getAttribute('title')||cells[0].getAttribute('data-hmk-help')||'')}" data-hmk-help="${esc(cells[0].getAttribute('data-hmk-help')||cells[0].getAttribute('title')||'')}">${cells[0].innerHTML}</div><dl class="folio-catalog-stats">${fields}</dl><div class="folio-catalog-foot"><div class="folio-catalog-details">${cells.at(-2)?.innerHTML||''}</div><div class="folio-catalog-actions">${cells.at(-1)?.innerHTML||''}</div></div></article>`;
}
// The completed-step map is intentionally cleared when editing an earlier
// chapter. Keep only the furthest visited page number as UI navigation state.
// No rolls, choices, validation flags or character data are inferred from it.
const HMK_CREATION_REACH_KEY='hmk-ledger-creation-reached-v1:';
function creationReachableStep(actor,creation){
 if(!actor?.id)return Math.max(1,Number(creation?.step)||1);
 const key=HMK_CREATION_REACH_KEY+actor.id;
 let previous=1;
 try{previous=Number(localStorage.getItem(key))||1}catch{}
 const completed=Math.max(0,...Object.keys(creation?.completed||{}).filter(k=>creation.completed[k]).map(Number).filter(Number.isInteger));
 const terminal=['auto-generated','review-required','complete'].includes(creation?.status)?14:1;
 const reached=Math.max(1,previous,Number(creation?.step)||1,completed,terminal);
 const safe=Math.min(14,reached);
 if(safe>previous){try{localStorage.setItem(key,String(safe))}catch{}}
 return safe;
}
