function libraryFieldHelp(label){
 const raw=String(label||'').trim();
 const k=({draw:'Draw',drw:'DRW',Draw:'Draw',drawStrength:'Draw',baseRange:'Dostřel',baseRangeFt:'Základní dostřel (ft)',hft:'HFT',lng:'LNG',weightLb:'Hmotnost',quality:'WQ'})[raw]||raw;
 return LIBRARY_FIELD_HELP[k]||LIBRARY_SPECIAL_HELP[k]||({quality:LIBRARY_FIELD_HELP.WQ,heft:LIBRARY_FIELD_HELP.Heft,length:LIBRARY_FIELD_HELP.Délka,zoneDie:'Kostka určení tělesné zóny zásahu.',baseRangeFt:LIBRARY_FIELD_HELP['Základní dostřel (ft)'],impactDie:'Kostka Impact pro daný režim útoku.',impactModifier:'Modifikátor k hodu Impact.',aspect:'Typ způsobeného poškození.',material:LIBRARY_FIELD_HELP.Materiál,weightLb:LIBRARY_FIELD_HELP.Hmotnost,pricePence:LIBRARY_FIELD_HELP.Cena}[k]||'Tento specifický atribut nemá v katalogu ověřenou samostatnou definici; jeho použití určuje příslušné pravidlo daného předmětu.');
}
function catalogParameters(item){
 // Czech rendering of catalogue *reference notes*; source objects remain unchanged.
function catalogNoteInCzech(label,value){
 if(typeof value!=='string')return value;
 const key=String(label||'').trim().toLocaleLowerCase('cs');
 if(!['poznámky','poznámka k pokrytí','pokryté lokace','krytí','coverage','notes','coverage note'].includes(key))return value;
 const known={
  'Location codes from p.118; layering, Bulk, ENC and armour totals not calculated.':'Kódy anatomických lokalit podle strany 118. Vrstvení, Bulk, ENC ani výsledná ochrana zbroje zde nejsou vypočítány.',
  'Anatomical dots from p.118; rigid coverage, ENC, layering and suit totals not calculated.':'Anatomické značky podle strany 118. Tuhost krytí, ENC, vrstvení ani souhrnné hodnoty kompletu zde nejsou vypočítány.',
  'p118 verified anatomical coverage; legality of combined layers still requires audit':'Anatomické krytí ověřené podle strany 118; přípustnost kombinovaných vrstev je nutné ještě ověřit.',
  'none':'žádné','front-only':'pouze zepředu','rigid':'tuhé krytí','standard':'běžné krytí'
 };
 if(known[value])return known[value];
 if(value.startsWith('NOT combat-ready: '))return 'Dosud neověřeno pro bojové použití: '+value.slice('NOT combat-ready: '.length);
 return value;
}

 const p=item.properties||{};
 const labels={draw:'Draw',drawStrength:'Draw',drw:'DRW',shaftWeight:'Shaft Weight',volleyMultiplier:'VM',rangeMultiplier:'VM',quality:'Základní WQ',heft:'Heft',length:'Délka',zoneDie:'Kostka zóny',weightLb:'Hmotnost (lb)',pricePence:'Cena (d)',weaponClass:'Třída zbraně',defenceModifier:'Obranný modifikátor',impactTAModifier:'Modifikátor Impact TA',shieldModifier:'Modifikátor štítu',deflect:'Odklonění (Deflect)',material:'Materiál',encumbrance:'ENC',perceptionPenalty:'Postih vnímání',armArticleEncGroup:'Skupina podmíněného ENC',coverage:'Pokryté lokace',protection:'Ochrana',baseRangeFt:'Základní dostřel (ft)',traits:'Vlastnosti',notes:'Poznámky',use:'Použití',value:'Hodnota',defense:'Obrana',attack:'Útok',impact:'Impact',layers:'Vrstvy',alternateStrikeModes:'Alternativní útoky',verifiedModes:'Útočné režimy',verifiedTraits:'Ověřené vlastnosti',armourReduction:'Snížení ochrany zbroje',armourReductionCondition:'Podmínka snížení ochrany',blockModifier:'Modifikátor blokování',opponentDefenceModifier:'Modifikátor obrany protivníka',shieldDamageImpactBonus:'Bonus Impact proti štítu',possibleFaeriecraftMeleeBonus:'Možný bonus Faeriecraft v boji',slowOneHand:'Pomalé použití jednou rukou',halfSwordNoSharpEdge:'Poloviční meč bez ostrého ostří',tripUsesWeaponLength:'Podražení využívá délku zbraně',coveredLocations:'Pokryté anatomické lokace',coverageNote:'Poznámka k pokrytí',variants:'Varianty',couched:'Založená kopí (couched)',entangle:'Zapletení / zachycení',slow:'Pomalá zbraň',removeTrait:'Odebraná vlastnost',locationProtection:'Ochrana anatomických lokací',b:'Blunt',e:'Edge',p:'Point',f:'Fire/Frost',B:'Blunt',E:'Edge',P:'Point',F:'Fire/Frost',impactDie:'Kostka Impact',impactModifier:'Modifikátor Impact',aspect:'Typ poškození',name:'Název',modifier:'Modifikátor'};
 const human=v=>v===null||v===undefined?'—':typeof v==='boolean'?(v?'Ano':'Ne'):String(v);
 const niceKey=k=>labels[k]||String(k).replace(/([a-z])([A-Z])/g,'$1 $2').replace(/_/g,' ').replace(/^./,c=>c.toUpperCase());
 const table=(headers,rows)=>`<div class="catalog-scroll"><table class="catalog-spec"><thead><tr>${headers.map(x=>`<th scope="col" class="catalog-parameter-tip" tabindex="0" data-hmk-help="${esc(libraryFieldHelp(x))}">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((x,i)=>`<${headers[0]==='Parametr'&&i===0?'th scope="row"':'td'} class="${headers[0]==='Parametr'&&i===0?'catalog-property-name':'catalog-property-value'}" tabindex="0" data-hmk-help="${esc(libraryFieldHelp(headers[0]==='Parametr'?row[0]:headers[i]))}" title="${esc(libraryFieldHelp(headers[0]==='Parametr'?row[0]:headers[i]))}">${esc(human(headers[0]==='Parametr'?(row[0]==='Materiál'?displayArmourMaterial(x):catalogNoteInCzech(row[0],x)):x))}</${headers[0]==='Parametr'&&i===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 const modeText=m=>String(m.impactDie||'—')+(Number.isFinite(m.impactModifier)?(m.impactModifier>=0?'+':'')+m.impactModifier:'');
 const primary=Array.isArray(p.verifiedModes)?p.verifiedModes:[];
 const alternate=Array.isArray(p.alternateStrikeModes)?p.alternateStrikeModes:[];
 // The compact catalogue row already shows the first verified Impact and aspect.
 // Only render additional values; alternate strikes retain their distinct Impact.
 const modes=[...primary.map((m,index)=>({...m,displayName:m.name==='Primary'?'Základní útok':m.name||'Základní útok',isVisiblePrimary:index===0&&item.category==='weapon'})),...alternate.map(m=>({...m,displayName:m.name||'Alternativní útok',isVisiblePrimary:false}))];
 const modeRows=modes.map(m=>{
  const parts=[];
  if(!m.isVisiblePrimary){parts.push('Impact: '+modeText(m));if(m.aspect)parts.push('Typ: '+(({b:'Blunt',e:'Edge',p:'Point',f:'Fire/Frost'})[m.aspect]||m.aspect));}
  const zone=m.zoneDie||p.zoneDie;if(zone)parts.push('Zóna: '+zone);
  const length=m.length||p.length;
  if(length&&(p.baseRangeFt!==undefined||String(length)!==String(p.length)))parts.push('Délka: '+length);
  for(const [k,v] of Object.entries(m)){
   if(['name','displayName','isVisiblePrimary','impactDie','impactModifier','aspect','zoneDie','length'].includes(k))continue;
   parts.push(niceKey(k)+': '+(v&&typeof v==='object'?'viz podrobnosti':human(v)));
  }
  return [m.displayName,parts.join(' · ')];
 }).filter(row=>row[1]);
 const modeTable=modeRows.length?`<h4>Další údaje útočných režimů</h4><div class="catalog-scroll"><table class="catalog-spec"><thead><tr><th>Režim</th><th>Nezobrazené parametry</th></tr></thead><tbody>${modeRows.map(([name,description])=>`<tr><td>${esc(name)}</td><td>${description.split(' · ').map(piece=>{const colon=piece.indexOf(':');const term=colon>0?piece.slice(0,colon):piece;const help=libraryFieldHelp(term);return `<span class="catalog-parameter-tip" tabindex="0" data-hmk-help="${esc(help)}">${esc(piece)}</span>`;}).join(' · ')}</td></tr>`).join('')}</tbody></table></div>`:'';
 const protection=p.locationProtection;
 const locRows=protection&&typeof protection==='object'&&!Array.isArray(protection)?Object.entries(protection).filter(([,v])=>v&&typeof v==='object'&&!Array.isArray(v)).map(([loc,v])=>[loc,v.b??v.B??'—',v.e??v.E??'—',v.p??v.P??'—',v.f??v.F??'—']):[];
 // The row shows the protection b/e/p/f of the first location; do not
 // repeat the same four numbers for locations whose protection is identical.
 const sameProtection=(a,b)=>a.slice(1).every((v,i)=>String(v)===String(b[i+1]));
 const baseProtection=locRows[0];
 const identicalProtection=baseProtection&&locRows.every(row=>sameProtection(row,baseProtection));
 const locTable=identicalProtection
  ?`<h4>Pokryté anatomické lokace</h4><p>${locRows.map(row=>esc(row[0])).join(' · ')}</p>`
  :locRows.length?`<h4>Ochrana dalších anatomických lokací</h4><p class="tiny muted">Základní ochrana prvního místa (${esc(locRows[0][0])}) je uvedena v přehledu předmětu.</p>${table(['Lokace','Blunt','Edge','Point','Fire/Frost'],locRows.slice(1))}`:'';
 // Only show scalar properties that have not already been printed in the row.
 const visible=new Set(['weightLb']);
 if(p.pricePence!==undefined)visible.add('pricePence');
 else if(p.pricePerDozenPence!==undefined)visible.add('pricePerDozenPence');
 if(item.category==='weapon'){
  visible.add('quality');
  if(p.baseRangeFt!==undefined)visible.add('baseRangeFt');
  else {visible.add('heft');visible.add('length');}
 }else if(item.category==='shield'){
  visible.add('quality');visible.add(p.shieldModifier!==null&&p.shieldModifier!==undefined?'shieldModifier':'blockModifier');visible.add('deflect');
 }else if(item.category==='armor'){
  visible.add('material');visible.add('encumbrance');visible.add('printedEncCode');
 }else if(p.projectileKind){
  visible.add('projectileKind');visible.add(p.shaftWeight?'shaftWeight':'slingProjectileForm');visible.add('impactDie');
 }else{
  visible.add(p.skill?'skill':'use');visible.add('quality');
 }
 const scalar=Object.entries(p).filter(([key,v])=>!visible.has(key)&&v!==null&&v!==undefined&&typeof v!=='object');
 const scalarTable=scalar.length?table(['Parametr','Hodnota'],scalar.map(([k,v])=>[niceKey(k),k==='material'?displayArmourMaterial(v):v])):'';
 // Recursive structured-data renderer for custom equipment: text and tables only.
 // Bound depth avoids infinite recursion for malformed user-provided objects.
 const describe=(v,depth=0)=>{
  if(depth>7)return '<span class="muted">Příliš hluboká struktura – podrobnosti nejsou zobrazeny.</span>';
  if(v===null||typeof v!=='object')return `<span>${esc(human(v))}</span>`;
  if(Array.isArray(v)){
   if(!v.length)return '<span class="muted">Bez záznamů</span>';
   return `<ol class="catalog-data-list">${v.map(x=>`<li>${describe(x,depth+1)}</li>`).join('')}</ol>`;
  }
  const entries=Object.entries(v);
  if(!entries.length)return '<span class="muted">Bez údajů</span>';
  if(entries.every(([,x])=>x===null||typeof x!=='object'))return table(['Parametr','Hodnota'],entries.map(([k,x])=>[niceKey(k),catalogNoteInCzech(niceKey(k),human(x))]));
  return `<div class="catalog-data-nested">${entries.map(([k,x])=>`<div class="catalog-complex"><strong class="catalog-parameter-tip" tabindex="0" data-hmk-help="${esc(libraryFieldHelp(niceKey(k)))}" >${esc(niceKey(k))}</strong>${describe(x,depth+1)}</div>`).join('')}</div>`;
 };
 const skipped=new Set(['verifiedModes','alternateStrikeModes','locationProtection']);
 const complex=Object.entries(p).filter(([k,v])=>!skipped.has(k)&&v!==null&&typeof v==='object');
 const extras=complex.length?`<h4>Další vlastnosti a pravidla</h4>${complex.map(([k,v])=>`<div class="catalog-complex"><strong class="catalog-parameter-tip" tabindex="0" data-hmk-help="${esc(libraryFieldHelp(niceKey(k)))}" >${esc(niceKey(k))}</strong>${describe(v)}</div>`).join('')}`:'';
 const remainingProtection=protection!==undefined&&!locRows.length?`<h4>Ochrana</h4>${describe(protection)}`:'';
 const categoryLabel={weapon:'Zbraň',shield:'Štít',armor:'Zbroj',other:'Ostatní předmět'}[item.category]||'Předmět';
 const noData=!Object.keys(p).length?'<p class="muted">U této položky zatím nejsou evidovány parametry.</p>':!scalarTable&&!modeTable&&!locTable&&!extras&&!remainingProtection?'<p class="muted">Všechny dostupné parametry jsou již uvedeny v řádku předmětu.</p>':'';
 return `<details class="catalog-parameters"><summary title="${esc(libraryFieldHelp('Úplné údaje'))}">⚙ Zobrazit parametry · ${esc(categoryLabel)}</summary><div class="catalog-parameters-inner">${scalarTable}${modeTable}${locTable}${extras}${remainingProtection}${noData}</div></details>`;
}
