 const weapons=chars.flatMap(c=>data.inventory.filter(x=>x.characterId===c.id&&['main_hand','off_hand'].includes(x.slot)&&x.snapshot?.category==='weapon').map(x=>({id:x.id,owner:c,name:x.snapshot.name})));
