function hskAlchemySVHelpers(form,primary){
 if(form?.id!=='skill-value-form')return [];
 const ids=[form.elements.namedItem('assist1')?.value||'',form.elements.namedItem('assist2')?.value||''].filter(Boolean);
 const routine=hskSelectedSRRoutine(form,primary,'A');
 if(ids.length&&routine?.id!=='alchemy-elixir')throw Error('Alchemy Assistance smí být použita pouze pro doloženou přípravu elixíru');
 if(!ids.length)return [];
 if(primary!=='Alchemy')throw Error('Alchemy Assistance vyžaduje primární dovednost Alchemy');
 const helpers=skillAssistantMLs(form,primary);
 if(helpers.some(x=>x.mastery.ml<40))throw Error('Alchemy Assistant musí mít Alchemy ML40+ (HMK 268)');
 return helpers;
}
function hskResolveSide({person,form,side,helpers=[]}){
 const info=hskFields(form,side),mastery=skillActorMastery(person,info.primary),secs=hskValidatedSecondaries(person,info);
 if(form.id==='skill-value-form')helpers=hskAlchemySVHelpers(form,info.primary);
 const sr=hskSecondaryRoll(form,person,info,side);
 const ctx=skillAutoFor(person,info.primary,form,side);
 const footpad=data.campaignClock?footpadSkillEvidence({journal:data.journal,campaignId:campaignKey(data.campaignClock),
  minute:data.campaignClock.minute,actorId:person.id,skill:info.primary,
  auralShockLevels:person.hmk?.arcane?.auralShockLevels??0,
  silenceConfirmed:false}):null;
 const effectiveMastery=footpad?footpadMastery(mastery,footpad):mastery;
 const resolved=skillResolvedResult({mastery:effectiveMastery,form,dieKey:'roll'+side,condition:ctx.condition,trauma:ctx.trauma,
  secondaryMLs:secs.map(x=>x.ml),assistants:helpers.map(x=>x.mastery.ml),gmModifier:hskGMModifier(form,side)});
 const die=resolved.die,raw=hskApplySRResult(resolved.result,sr);
 const erudition=data.campaignClock?eruditionSkillEvidence({journal:data.journal,campaignId:campaignKey(data.campaignClock),
  minute:data.campaignClock.minute,actorId:person.id,skill:info.primary,
  auralShockLevels:person.hmk?.arcane?.auralShockLevels??0}):null;
 const eruditionResult=applyEruditionSkillResult(raw,erudition);
 const result=footpad?.modifier?{...eruditionResult,footpadBaseML:mastery.ml,
  footpadBonusML:footpad.modifier,footpadSourceIds:[...footpad.sourceIds],footpadSourcePage:272}:eruditionResult;
 const consequence=classifySkillConsequence({actor:person,skill:info.primary,result,trauma:ctx.trauma,context:'general'});
 return {person,mastery,secs,ctx,die,result,sr,erudition,footpad,consequence,info,helpers,emlRange:criticalEMLRange(result,ctx)};
}
function hskResultText(side,{person,mastery,secs,ctx,die,result,sr}){
 const breakdown='ML '+mastery.ml+secs.map(x=>' '+hskSigned(x.modifier)+' '+x.name).join('')+
  ctx.breakdown.map(x=>' '+hskSigned(x.value)+' '+x.label).join('')+' '+hskSigned(Number.isSafeInteger(result.gmModifier)?result.gmModifier-ctx.modifier:0)+' GM situace';
 const warnings=(ctx.armourWarnings.length?'\nGM výbava: '+ctx.armourWarnings.join('; '):'')+(ctx.armourIsProvisional?'\nPŘEDBĚŽNÝ výsledek: '+ctx.provisionalArmour.join('; '):'');
 return side+' · '+person.name+' / '+mastery.name+' | '+breakdown+' = EML '+(result.eml??'—')+
  '\nPrimární '+(result.forcedCF?'vynucené CF bez hodu':'d100 ('+result.roll+')')+' → '+(result.victoryLevel||result.level)+
  (result.splitCF?' ['+result.splitCF+(result.splitCF==='CF0'?' / potenciální Fumble':' / potenciální Stumble')+' – jen při předepsané činnosti]':'')+
  (result.footpadSourceIds?'\nFootpad (HMK 272) · Primary ML +'+result.footpadBonusML+' ('+result.footpadSourceIds.join(', ')+'); původní ML '+result.footpadBaseML+'.':'')+
  (result.eruditionSourceIds?'\nErudition (HMK 271) · doložené S → CS ('+result.eruditionSourceIds.join(', ')+'); původní d100 / EML zůstávají.':'')+
  (sr?'\nSecondary Roll '+sr.name+' · TN '+sr.tn+' (HMK str. '+sr.sourcePage+') · '+(sr.roll===null?'bez hodu, dovednost neosvojena':'d10 ('+sr.roll+')')+' → '+(sr.success?'S':'F')+'; '+sr.effect:'')+warnings;
}
// Voluntary, append-only HMK p.61 tiebreak. Never reroll/overwrite original d100 proof.
let hskTieDiceOrigin=null,hskTieDiceAttempts=[];
document.addEventListener('submit',event=>{
 const form=event.target;if(form?.id!=='skill-tiebreak-form')return;
 event.preventDefault();event.stopImmediatePropagation();
 const slot=form.querySelector('.hsk-tiebreak-message');
 try{
  const originId=form.elements.namedItem('originId')?.value;
  const saved=data.journal.find(x=>x.id===originId&&x.characterId===selected&&x.skillTestProof?.type==='opposed-success-test');
  if(!saved)throw Error('Původní Opposed Test nebyl nalezen v historii aktuální postavy.');
  const proof=saved.skillTestProof;
  if(!proof?.comparison?.tie||!canResolveOpposedTie(proof.a,proof.b,{persuasion:!!proof.comparison.persuasionTie}))throw Error('HMK str.61/138: rozstřel jen při doložené remíze; F/F a CF/CF pouze u Persuasion.');
  if(data.journal.some(x=>x.skillTestProof?.type==='opposed-tiebreak'&&x.skillTestProof.originSkillTestId===originId))throw Error('Tato remíza již byla rozhodnuta.');
  const opponent=character(proof.opponentId);if(!opponent)throw Error('Oponent již není dostupný.');
  if(hskTieDiceOrigin!==originId){hskTieDiceOrigin=originId;hskTieDiceAttempts=[];}
  const requiresD10=proof.a.roll===proof.b.roll&&proof.a.ml===proof.b.ml;
  const da=requiresD10?skillDie(form,'tieD10A',10):null;
  const db=requiresD10?skillDie(form,'tieD10B',10):null;
  const decision=resolveOptionalOpposedTie(proof.a,proof.b,{d10A:da?.roll??null,d10B:db?.roll??null,persuasion:!!proof.comparison.persuasionTie});
  if(requiresD10)hskTieDiceAttempts.push({d10A:da.roll,d10B:db.roll,originA:da.origin,originB:db.origin});
  if(decision.requiresAnotherD10){if(slot)slot.textContent='D10 '+da.roll+' a '+db.roll+' se shodují. Obě strany musí hodit d10 znovu; původní d100 zůstává beze změny.';return;}
  const winner=decision.winner==='a'?character(selected):opponent;
  const methodText=decision.method==='higher-d100'?'vyšší původní d100':decision.method==='higher-ml'?'vyšší původní Primary ML':'dodatečné hody d10';
  const narrative=skillNarrativeTiebreak({winnerName:winner.name,method:decision.method,attackerName:character(selected).name,defenderName:opponent.name,primary:proof.skills?.[0]||'Skill'});
  const body=(proof.comparison.persuasionTie?'Povinný rozstřel Persuasion · HMK str. 138':'Dobrovolný rozstřel · HMK str. 61')+'\nPůvodní Opposed Test: '+saved.title+' ['+originId+']'+
   '\nPůvodní výsledky: '+proof.a.level+' / '+proof.b.level+'; d100 '+proof.a.roll+' / '+proof.b.roll+'; ML '+proof.a.ml+' / '+proof.b.ml+
   '\nRozhodlo: '+methodText+(requiresD10?' ('+hskTieDiceAttempts.map(x=>x.d10A+':'+x.d10B).join(', ')+')':'')+
   '\nVítěz: '+winner.name+' · Victory Stars: 1 ★'+hskNarrativeBlock(narrative);
  recordSkillEvidence('Opposed · rozstřel · '+(proof.skills?.[0]||'Skill Test'),body,{type:'opposed-tiebreak',actorId:selected,
   opponentId:proof.opponentId,originSkillTestId:originId,originalRolls:[proof.a.roll,proof.b.roll],originalMLs:[proof.a.ml,proof.b.ml],
   originalLevels:[proof.a.level,proof.b.level],method:decision.method,winnerId:winner.id,stars:1,sourcePage:61,
   diceAttempts:requiresD10?hskTieDiceAttempts.map(x=>({...x})):[],gmNarrative:narrative,result:decision,sourcePage:proof.comparison.persuasionTie?138:61},'hsk-result-secondary');
  hskTieDiceOrigin=null;hskTieDiceAttempts=[];
 }catch(err){if(slot)slot.textContent='Rozstřel nebyl uložen: '+err.message;else alert(err.message);}
},true);
function hskHighlightRequired(form,name,message){
 const field=form?.elements?.namedItem(name);if(!field?.classList)return false;
 for(const el of form.querySelectorAll('.hsk-required-invalid')){el.classList.remove('hsk-required-invalid');el.removeAttribute('aria-invalid');el.closest('label')?.classList.remove('hsk-required-invalid-label');}
 field.classList.add('hsk-required-invalid');field.setAttribute('aria-invalid','true');
 field.closest('label')?.classList.add('hsk-required-invalid-label');
 (field.closest('label')||field).scrollIntoView({block:'center',behavior:'smooth'});
 try{field.focus({preventScroll:true})}catch{}
 const out=form.querySelector('output');if(out)out.textContent='Doplňte pole „'+(field.closest('label')?.textContent?.trim()||name)+'“. '+message;
 return true;
}
