document.addEventListener('submit',e=>{
 const f=e.target;if(!f?.matches?.('[data-herb-admin]'))return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  const clock=data.campaignClock;if(!clock)throw Error('Chybí kalendář');
  const fd=new FormData(f),actorId=String(fd.get('actorId')||''),targetRef=String(fd.get('targetRef')||''),
   [targetId,woundPart='']=targetRef.split('::'),method=String(fd.get('methodOverride')||fd.get('method')||'');
  const memberIds=calendarMemberIds(clock,data.characters).map(c=>c.id);
  const target=character(targetId),potionRow=data.journal.find(x=>x.id===fd.get('completeId'));
  const type=potionRow?.calendarHerbPotionComplete?.herbType;
  if(type==='soporific'&&(activeHerbalSoporific(target?.hmk?.combatState)||pendingSoporificTests(data.journal,campaignKey(clock)).some(t=>t.targetId===targetId)||pendingSoporificEffects(data.journal,campaignKey(clock)).some(t=>t.targetId===targetId)))throw Error('Soporific: příjemce už má aktivní nebo nevyřešený účinek. Další dávku musí GM vyřešit mimo tuto automatickou větev.');
  if(type==='poison'&&potionRow?.calendarHerbPotionComplete?.sv>=15)throw Error('Poison: nekladný interval 15 − SV vyžaduje rozhodnutí GM; automaticky jej neurčujeme');
  const physicallyBottled=vialBinding(data.journal,campaignKey(clock),String(fd.get('completeId')));
  if(physicallyBottled){const pos=vialState(data.journal,campaignKey(clock),String(fd.get('completeId')),clock.minute);
   const item=data.inventory.find(x=>x.id===pos?.vialId);
   if(!item||item.characterId!==actorId||item.quantity!==1||!['carried','none'].includes(item.slot)||item.sourceItemId!==PRINTED_VIAL||item.snapshot?.properties?.weightLb!==0.25)
    throw Error('Fyzická lahvička musí být u současného podávajícího; Truhlice není dostupná.');}
  const poisonSourceId=type==='antivenin'?decodeURIComponent(woundPart):'';
  const emeticOnsetD6=type==='emetic'?Number(fd.get('emeticOnsetD6')):null;
  const emeticOnsetOrigin=type==='emetic'?(f.elements.namedItem('emeticOnsetD6')?.dataset.herbGenerated===String(emeticOnsetD6)?'cryptographic-software-die':'manual'):'';
  const woundId=['curative','coagulant'].includes(type)?woundPart:'';
  if(type==='antivenin'&&!target?.hmk?.combatState?.toxinCourses?.some(t=>t.sourceId===poisonSourceId&&['incubating','active'].includes(t.status)))
   throw Error('Antivenin: vybraná otrava není aktivní nebo nemá doložený původ v této kampani');
  if(['curative','coagulant'].includes(type)){
   const wound=target?.hmk?.combatState?.wounds?.find(w=>w.id===woundId&&!w.healed);
   if(!wound||type==='coagulant'&&!wound.bleeding)throw Error('Není doložená odpovídající aktivní rána');
   if(type==='curative'&&(wound.area||wound.healing?.area))throw Error('Area Injury podle HMK 75 vyžaduje pět skutečných dávek; jednorázové podání není přípustné.');
  }
  const proof=createHerbPotionAdministration({journal:data.journal,campaignId:campaignKey(clock),minute:clock.minute,
   actorId,completeId:String(fd.get('completeId')),targetId,method,woundId,poisonSourceId,emeticOnsetD6,emeticOnsetOrigin,gmConfirmed:!!fd.get('gmConfirmed'),memberIds,
   combatAnchor:type==='coagulant'||type==='emetic'||(type==='antivenin'||type==='paralytic'||type==='soporific'||type==='poison')&&potionRow?.calendarHerbPotionComplete?.potency===3&&fd.get('combatAnchorConfirmed')?(()=>{
    if(!fd.get('combatAnchorConfirmed')||!encounterSelection.has(targetId)||(type==='emetic'||(type==='paralytic'||type==='soporific'||type==='poison')&&potionRow?.calendarHerbPotionComplete?.potency===3)&&(!combatInitiativeSequence||combatInitiativeSequence.timelineId!==combatInjuryTimelineId||combatInitiativeSequence.round!==combatClock.round))
     throw Error('Chybí GM potvrzená bojová osa a účast pacienta ve střetnutí');
    return {confirmedByGM:true,round:combatClock.round,campaignMinute:clock.minute,timelineId:combatInjuryTimelineId};
   })():null});
  const applicationRow={id:uuid(),characterId:actorId,calendarCampaignId:campaignKey(clock),campaignMinute:clock.minute,
   createdAt:stamp(),title:'HMK 75 · podání bylinného lektvaru',body:'Doložené podání bez posunu GM času. Následné testy řeší příslušný původní modul.',calendarHerbPotionAdminister:proof};
  let herbalPoison=null;
  if(type==='poison'&&potionRow?.calendarHerbPotionComplete?.potency!==3){
   if(combatInitiativeSequence)throw Error('Poison Mild/Strong během Initiative musí GM vést přímo v bojové proceduře; tento minutový průchod je mimo boj');
   const poisonState=persistentStateOf(target),round=Math.max(1,combatClock.round||1,poisonState.lastRound||0);
   herbalPoison=prepareHerbalPoisonExposure({journal:[...data.journal,applicationRow],
    campaignId:campaignKey(clock),applicationId:applicationRow.id,minute:clock.minute,actor:target,
    state:poisonState,round,periodMinutes:Number(fd.get('poisonPeriodMinutes')),
    symptomD10s:[1,2,3,4].map(i=>Number(fd.get('poisonSymptom'+i))),
    actualExposureConfirmed:!!fd.get('poisonStandardConfirmed'),
    standardLethalConfirmed:!!fd.get('poisonStandardConfirmed'),gmConfirmed:!!fd.get('gmConfirmed')});
  }
  if(mutate(()=>{
   data.journal.push(applicationRow);
   if(herbalPoison){
    if(persistentStateOf(target).events.some(e=>e.id===herbalPoison.report.id))throw Error('Poison je již aktivní');
    synchronizeCombatInjuries(target,herbalPoison.state);
    data.campaignClock=anchorCampaignOrigin(data.campaignClock,{kind:'poison',characterId:target.id,
     eventId:uuid(),combatEventId:herbalPoison.course.id,source:'confirmed-combat'});
    data.journal.push({id:uuid(),characterId:target.id,calendarCampaignId:campaignKey(clock),campaignMinute:clock.minute,
     createdAt:stamp(),title:'Herbal Poison · doložené požití · HMK 75/186',
     body:'Podání '+applicationRow.id+'; HR'+herbalPoison.course.initialHR+'; nástup '+herbalPoison.proof.onsetCount+' '+herbalPoison.proof.onsetUnit+'; period '+herbalPoison.course.periodMinutes+' min; bez okamžitého stavového účinku.',
     calendarHerbPoisonExposure:herbalPoison.proof,
     skillTestProof:{type:'poison-start',sourceId:herbalPoison.course.sourceId,actorId:target.id,course:herbalPoison.course}});
   }
  }))notice=herbalPoison?'Poison byl podán a ve stejné transakci založil skutečnou Poison Course expozici. Nástup až po uplynutí doloženého času.':'Podání zapsáno s pravidlovým původem. Následný zdravotní hod zatím není automaticky vyhodnocen.';
 }catch(err){alert('Podání nebylo uloženo: '+err.message)}
},true);
