/** A blocking GM clock check must hand off to its ORIGINAL, source-linked rule executor.
 * This is navigation only: never fabricate dice, facts or time changes. */
function explainAndOpenBlockedCalendarTerm(err,targetMinute){
 const message=String(err?.message||err);
 if(!/povinný termín|časový závazek|přeskočit nevyřízenou/.test(message))return false;
 const clock=data.campaignClock;if(!clock)return false;
 const agenda=campaignCalendarAgenda(clock,data.characters,data.journal);
 const due=[...(agenda.unknown||[]),...(agenda.all||[])].filter(x=>x.minute<=clock.minute&&x.minute<targetMinute)
  .sort((a,b)=>a.minute-b.minute)[0];
 if(!due)return false;
 const actor=character(due.characterId);
 window.alert('Čas nebyl změněn. Povinná kontrola: '+(actor?.name||due.name)+' · '+due.description+' · '+displayCampaignMinute(due.minute)+'. Po zavření tohoto okna se otevře správný formulář.');
 if(actor&&due.sourceId&&due.kind){selected=actor.id;focusCalendarRuleAction(actor,due.kind,due.sourceId,due.elapsedMinutes);return true;}
 view='calendar';calendarLanding=false;activeCalendarSection='overview';render();
 const row=[...document.querySelectorAll('[data-cal-agenda]')].find(n=>n.dataset.calAgenda===due.id);
 row?.scrollIntoView({block:'center',behavior:'auto'});row?.focus({preventScroll:true});
 return true;
}
document.addEventListener('submit',e=>{
 const f=e.target;
 if(!['campaign-quick-advance-form','campaign-plan-form','campaign-tr-origin-form'].includes(f.id))return;
 e.preventDefault();e.stopImmediatePropagation();
 const v=Object.fromEntries(new FormData(f)),n=x=>/^\d+$/.test(String(x??''))?Number(x):NaN;
 try{
  if(!data.campaignClock)throw Error('Nejdříve založte kampaň');
  if(f.id!=='campaign-quick-advance-form'&&v.gmConfirmed!=='yes')throw Error('Akci musí potvrdit GM');
  if(f.id==='campaign-tr-origin-form'){
   const next=setCampaignTROrigin(data.campaignClock,{year:n(v.year),month:n(v.month),day:n(v.day),eventId:uuid(),confirmed:true});
   if(!window.confirm('Přiřadit '+formatTRDate(campaignTRDate(next,next.minute))+' ke skutečnému dni kampaně? Datum již nepůjde nenápadně změnit.'))return;
   mutate(()=>{data.campaignClock=next;});return;
  }
  if(f.id==='campaign-quick-advance-form'){
   if(combatInitiativeSequence)throw Error('Při aktivním Initiative nelze samostatně posouvat čas kampaně');
   const delta=n(v.deltaMinutes),next=advanceCampaignCalendar(data.campaignClock,{deltaMinutes:delta,eventId:uuid(),reason:v.reason,gmConfirmed:true,characters:data.characters,journal:data.journal});
   if(!window.confirm('Potvrdit skutečné plynutí času do '+displayCampaignMinute(next.minute)+'? Nástup bez hodu se automaticky zapíše; splatné hody se samy nevynechají.'))return;
   mutate(()=>{data.campaignClock=next;applyDeterministicCalendarOnsets();},{gmClockAdvance:true});return;
  }
  const minute=(n(v.day)-1)*DAY_MINUTES+n(v.hour)*60+n(v.minute), duration=n(v.durationDays)*DAY_MINUTES+n(v.durationHours)*60+n(v.durationMinutes);
  if(!Number.isSafeInteger(minute)||!Number.isSafeInteger(duration)||duration<0)throw Error('Zadejte platný den a délku trvání');
  if(v.characterId&&!character(v.characterId))throw Error('Postava není v registru');
  if(v.requiresAction==='yes'&&minute<data.campaignClock.minute&&v.trigger!=='end')throw Error('Povinnou nevyřízenou událost nelze plánovat zpětně; použijte běžnou historickou poznámku');
  const skill=String(v.skill||'').trim();
  if(skill&&(v.destination!=='skills'||!v.characterId||!availableMasteries(character(v.characterId)).some(m=>m.name===skill&&m.ml>0)))
   throw Error('Předvolená dovednost není doložena u vybrané postavy nebo nevede do Skill Tests.');
  const next=addGMCalendarPlan(data.campaignClock,{id:uuid(),eventId:uuid(),title:v.title,note:v.note||'',place:v.place||'',characterId:v.characterId||'',skill,minute,endMinute:minute+duration,destination:v.destination,requiresAction:v.requiresAction==='yes',trigger:v.trigger,confirmed:true});
  if(!window.confirm('Zapsat událost „'+v.title+'“ na '+displayCampaignMinute(minute)+'?'))return;
  if(mutate(()=>{data.campaignClock=next;}))calendarUI.prefillMinute=null;
 }catch(err){const v=Object.fromEntries(new FormData(f));
  const delta=Number(v.deltaMinutes)||0;if(f.id!=='campaign-quick-advance-form'||!explainAndOpenBlockedCalendarTerm(err,data.campaignClock.minute+delta))alert('Kalendář nebyl změněn: '+err.message)}
},true);
/** Purely deterministic onsets: the original Poison/Disease procedures
 * perform every state change. This function runs IN the same normal atomic
 * clock mutation and only for a precisely attested, already-due source.
 * Any conflicting condition aborts the complete clock advance; no time or
 * other character state is committed. Course dice remain explicit.
 */
function applyDeterministicCalendarOnsets(){
 if(combatInitiativeSequence)throw Error('Nástup během Initiative musí vyhodnotit Combat');
 const clock=data.campaignClock;if(!clock)return;
 const agenda=campaignCalendarAgenda(clock,data.characters,data.journal);
 for(const onset of automaticAilmentOnsets(agenda,data.characters,clock.minute)){
  const {event,actor,course}=onset;
  const state=persistentStateOf(actor);
  // Re-evaluate against the live state after any earlier onset in this jump.
  // Competing exposures will be rejected by the original rules executor.
  const active=(event.kind==='poison'?state.toxinCourses:state.diseaseCourses)?.find(t=>t.id===course.id);
  if(active?.status!=='incubating')continue;
  const anchor=getCampaignEpisodeAnchor(clock,event.kind,actor.id,course.id);
  if(!anchor||event.minute!==anchor.minute+course.onsetMinutes)
   throw Error('Nástup nemá jednoznačný doložený čas '+event.kind);
  const round=Math.max(1,combatClock.round||1,state.lastRound||0);
  const args={actor,state,sourceId:course.sourceId,round,
   elapsedMinutes:course.onsetMinutes,gmConfirmed:true};
  const result=event.kind==='poison'?preparePoisonOnset(args):prepareDiseaseOnset(args);
  synchronizeCombatInjuries(actor,result.state);
  data.journal.push({id:uuid(),characterId:actor.id,createdAt:stamp(),
   calendarCampaignId:campaignKey(clock),campaignMinute:event.minute,
   title:(event.kind==='poison'?'Poison':'Disease')+' · automatický nástup · HMK 183–186',
   body:'Doložený čas '+displayCampaignMinute(event.minute)+'; zdroj '+course.sourceId+
    '; HR'+result.report.hr+'; žádný hod při samotném nástupu.',
   skillTestProof:{type:event.kind+'-onset',sourceId:course.sourceId,
    actorId:actor.id,automaticFromAttestedCalendar:true,
    report:structuredClone(result.report),originMinute:anchor.minute}});
 }
}
