// v93.562: verified reference-only livestock ownership; never fabricate Combat State.
document.addEventListener('submit',e=>{
 const form=e.target;if(!form?.matches?.('[data-hmk-livestock-acquire]'))return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  if(combatInitiativeSequence||!data.campaignClock)throw Error('Nákup zvířete je možný jen v kampani mimo Initiative.');
  const fd=new FormData(form),beastId=String(fd.get('beastId')||''),sp=livestockOffer(beastId),beast=BEASTS_P122.find(x=>x.id===beastId),ownerId=String(fd.get('ownerId')||''),mode=String(e.submitter?.value||'');
  const name=String(fd.get('beastName')||'').trim(),owner=character(ownerId),cid=campaignKey(data.campaignClock),minute=data.campaignClock.minute;
  if(!sp||!beast||!owner||!['buy','free'].includes(mode)||name.length<2||name.length>60)throw Error('Vyberte zvíře, vlastníka a jméno o délce 2–60 znaků.');
  if(data.characters.some(c=>(c.hmk?.livestock||[]).some(a=>a.campaignId===cid&&a.name.toLocaleLowerCase('cs')===name.toLocaleLowerCase('cs')))||data.characters.some(c=>c.name.toLocaleLowerCase('cs')===name.toLocaleLowerCase('cs')))
   throw Error('Zvíře musí mít unikátní jméno pro jednoznačné cestovní záznamy.');
  if(activeCampaignCashKey(owner)===undefined)throw Error('Majitel není členem právě zvolené kampaně.');
  if(mode==='buy')prepareLibraryPurchase(owner,beast.priceD,cid);
  if(!ask(mode==='buy'?`Koupit ${beast.name} (${name}) za ${beast.priceD}d pro ${owner.name}?`:`GM potvrzuje bezplatné převzetí ${beast.name} (${name}) postavou ${owner.name}?`))return;
  if(mutate(()=>{
   const live=character(ownerId),key=campaignKey(data.campaignClock),at=stamp();
   if(key!==cid||data.campaignClock.minute!==minute||combatInitiativeSequence||!live||activeCampaignCashKey(live)===undefined)throw Error('Mezitím se změnila kampaň nebo Initiative.');
   if(mode==='buy')prepareLibraryPurchase(live,beast.priceD,cid);
   const id=uuid(),txId=uuid();
   live.hmk??={};live.hmk.livestock??=[];
   live.hmk.livestock.push({id,name,beastId,ownerId,priceD:beast.priceD,mode,campaignId:cid,minute,maxMB:beast.maxMasteryBoosts,transactionId:txId});
   // Livestock is NEVER a carried Inventory Item. The actual animal belongs
   // to the stable; its cost is accounted in the immutable campaign cash ledger.
   if(mode==='buy')recordCampaignCoinAdjustment(live,{campaignId:cid,minute,id:txId,at,deltaPence:-beast.priceD,
     reason:'Nákup zvířete podle HMK 122: '+beast.name+' · '+name});
   data.journal.push({id:uuid(),characterId:ownerId,calendarCampaignId:cid,campaignMinute:minute,createdAt:at,title:'HMK 122 · '+(mode==='buy'?'nákup zvířete':'převzetí zvířete'),body:beast.name+' · '+name+' · '+(mode==='buy'?beast.priceD+'d':'bezplatně')+'; registr stáje; žádný automatický výcvik ani zdravotní stav',livestockAcquisition:{animalId:id,ownerId,beastId,name,priceD:beast.priceD,mode,transactionId:txId}});
  }))notice=`Do stáje bylo zařazeno ${name} (${beast.name}).`;
 }catch(err){alert('Pořízení zvířete: '+err.message)}
},true);
