// v11: Multi-line journal editor preserves timestamps and record identity.
function journalEditForm(x){return `<div class="editor-backdrop"><section class="panel editor-dialog" role="dialog" aria-modal="true" aria-labelledby="edit-log-title"><h2 id="edit-log-title">Upravit zápis deníku</h2><form id="journal-edit-form"><input type="hidden" name="journalId" value="${esc(x.id)}">${field('title','Nadpis',x.title||'')}${area('body','Text zápisu',x.body)}<div class="actions"><button type="submit">Uložit zápis</button><button type="button" class="secondary" data-action="cancel-editor">Zrušit</button></div></form></section></div>`}

document.addEventListener('click',e=>{const t=e.target.closest('[data-edit-log]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();const x=data.journal.find(x=>x.id===t.dataset.editLog&&x.characterId===selected);if(!x)return;if(!isPersonalNote(x))return alert('Pravidlový důkaz nelze ručně upravit.');if(x.combatProof||x.skillTestProof||x.calendarChestTransfer||x.calendarInventoryWaterFill||x.calendarInventoryWaterUse||x.calendarInventoryWaterTransfer||x.calendarInventoryWaterLoss||x.calendarInventoryRationLoss||x.calendarInventoryRationTransfer||x.calendarInventoryDisposition||x.calendarHerbEmeticShock||x.calendarHerbVialBinding||x.calendarHerbVialDiscard||x.calendarHerbWeaponPaste||x.calendarHerbWeaponPasteHit||x.calendarHerbWeaponResistance||x.calendarHerbWeaponPasteDiscard||x.calendarHerbParalyticEndurance||x.calendarHerbSoporificEnd||x.calendarHerbSoporificEffect)return alert('Potvrzený bojový důkaz je neměnný; opravujte pouze soukromé poznámky bez combatProof.');overlay=journalEditForm(x);render()},true);
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')!=='journal-edit-form')return;e.preventDefault();e.stopImmediatePropagation();const v=Object.fromEntries(new FormData(e.target));const x=data.journal.find(x=>x.id===v.journalId&&x.characterId===selected);if(!x)return alert('Zápis již neexistuje');if(!isPersonalNote(x))return alert('Pravidlový důkaz nelze ručně změnit.');if(x.combatProof||x.skillTestProof||x.calendarChestTransfer||x.calendarInventoryWaterFill||x.calendarInventoryWaterUse||x.calendarInventoryWaterTransfer||x.calendarInventoryWaterLoss||x.calendarInventoryRationLoss||x.calendarInventoryRationTransfer||x.calendarInventoryDisposition||x.calendarHerbVialBinding||x.calendarHerbVialDiscard||x.calendarHerbWeaponPaste||x.calendarHerbWeaponPasteHit||x.calendarHerbWeaponResistance||x.calendarHerbWeaponPasteDiscard||x.calendarHerbParalyticEndurance||x.calendarHerbSoporificEnd||x.calendarHerbSoporificEffect)return alert('Potvrzený bojový důkaz nelze ručně změnit.');if(mutate(()=>{const target=data.journal.find(row=>row.id===v.journalId&&row.characterId===selected);if(!target)throw Error('Zápis již neexistuje');if(!isPersonalNote(target))throw Error('Pravidlový záznam nelze upravit');if(target.combatProof||target.skillTestProof||target.calendarInventoryWaterLoss||target.calendarInventoryRationLoss||target.calendarHerbEmeticShock||target.calendarHerbWeaponPaste||target.calendarHerbWeaponPasteHit||target.calendarHerbWeaponResistance||target.calendarHerbWeaponPasteDiscard||target.calendarHerbSoporificEnd||target.calendarHerbSoporificEffect)throw Error('Potvrzený bojový důkaz nelze ručně změnit');target.title=v.title.trim()||'Bez názvu';target.body=v.body;target.updatedAt=stamp()})){overlay=null;render()}},true);

// Edit existing records without destroying IDs or journal timestamps.

document.addEventListener('click',e=>{
 const t=e.target.closest('[data-edit-skill],[data-edit-injury]');if(!t)return;
 const id=t.dataset.editSkill||t.dataset.editInjury;
 const c=character(selected);if(!c)return;
 if(t.dataset.editSkill){try{assertLegacyMutationAllowed(c)}catch(err){return alert(err.message)}if(combatInitiativeSequence)return alert('Během Initiative nelze mimo Combat měnit ML postavy.');const x=(c.hmk?.skills||[]).find(x=>x.id===id);if(!x)return;const name=prompt('Dovednost',x.name);if(name===null)return;if(!name.trim())return alert('Název je povinný');const sb=prompt('SB (prázdné = nezadáno)',x.sb??'');if(sb===null)return;const ml=prompt('ML (prázdné = nezadáno)',x.ml??'');if(ml===null)return;const parse=v=>v.trim()===''?null:Number(v);if([parse(sb),parse(ml)].some(n=>n!==null&&(!Number.isSafeInteger(n)||n<0||n>999)))return alert('SB a ML musí být celá nezáporná čísla');if(x.creationDerived&&!window.confirm('Jde o automaticky vypočtený Skill. Ruční úprava bude evidována jako GM override a původní pravidlový výpočet zůstane na kartě dohledatelný. Pokračovat?'))return;
 mutate(()=>{if(x.creationDerived){x.manualOverride={source:'GM Edit',priorSB:x.sb,priorML:x.ml,confirmedAt:stamp()};x.creationDerived=false;if(c.hmk?.creation)c.hmk.creation.status='review-required';}
 x.name=name.trim();x.sb=parse(sb);x.ml=parse(ml)});return}
 if(t.dataset.editInjury){if(combatInitiativeSequence)return alert('Během Initiative nelze měnit žádné zranění mimo Combat průvodce.');const x=(c.hmk?.injuries||[]).find(x=>x.id===id);if(!x)return;if(x.combatRecord===true)return alert('Potvrzenou bojovou ránu lze upravit jen pravidlovým přechodem, ne ručně v deníku.');const location=prompt('Lokalita zásahu',x.location);if(location===null)return;if(!location.trim())return alert('Lokalita je povinná');const severity=prompt('Závažnost',x.severity||'');if(severity===null)return;const description=prompt('Popis poranění',x.description||'');if(description===null)return;mutate(()=>{x.location=location.trim();x.severity=severity;x.description=description})}
},true);
// Capture phase handles new forms before the legacy form dispatcher.
document.addEventListener('submit',e=>{const f=e.target;if(!['hmk-profile-form','hmk-skill-form','hmk-injury-form','hmk-item-form'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();const v=Object.fromEntries(new FormData(f));if(f.id==='hmk-item-form'){if(!String(v.name||'').trim())return alert('Zadejte název');const current=editItem?item(editItem):null;if(current&&current.category!==v.category)return alert('Změna kategorie existujícího předmětu není podporována. Založte nový předmět.');const props={...(current?.properties||{})};for(const [k,val] of Object.entries(v))if(k.startsWith('spec_'))props[k.slice(5)]=val;if(v.category==='weapon'){
  try{props.verifiedModes=parseStructuredModes(v.verifiedModes);props.verifiedTraits=parseStructuredTraits(v.verifiedTraits)}catch(err){return alert(err.message)}
 }else if(v.category==='armor'){
  try{props.locationProtection=parseLocationProtection(v.locationProtection)}catch(err){return alert(err.message)}
 }
 const record={id:editItem||uuid(),name:v.name.trim(),category:v.category,description:v.description||'',source:v.source||'',properties:props};if(mutate(()=>{if(current)Object.assign(current,record);else data.items.push(record)})){overlay=null;render()}return}const c=character(selected);if(!c)return;const h=structuredClone(c.hmk||{});if(f.id==='hmk-profile-form'){try{assertLegacyMutationAllowed(c,'profile')}catch(err){return alert(err.message)}if(combatInitiativeSequence)return alert('Během Initiative se atributy bojovníka nemění mimo ověřený pravidlový průvodce.');const a={...(h.attributes||{})};for(const [k,val] of Object.entries(v)){if(k==='bio_creatureSizeReachModifier'){if(val==='')delete h.creatureSizeReachModifier;else if(!/^-?\d+$/.test(String(val))||!Number.isSafeInteger(Number(val)))return alert('Neplatný modifikátor Creature Size');else h.creatureSizeReachModifier=Number(val);}else if(k.startsWith('bio_'))h[k.slice(4)]=val;if(k.startsWith('attr_')){if(val==='')delete a[k.slice(5)];else{const n=Number(val);if(!Number.isSafeInteger(n)||n<0||n>(k==='attr_aberrance'?200:999))return alert('Neplatná charakteristika / Aberrance');a[k.slice(5)]=n}}}if(h.creation){
  if(h.folk!==c.hmk?.folk||h.ageGroup!==c.hmk?.ageGroup){
    if(!window.confirm('Edit Folk/Age Group zneplatní původní soubory fyzických hodů Attributes. Pokračovat?'))return;
    h.creation.attributeProof={};h.creation.skillDP={};h.creation.status='in-progress';
    for(let n=10;n<=14;n++)delete h.creation.completed[n];
    for(const key of ATTRIBUTES)delete a[key];
  }
  const changed=ATTRIBUTES.filter(key=>a[key]!==h.attributes?.[key]);
  if(changed.length&&!window.confirm('Edit změní '+changed.join(', ')+' a zruší důkazy fyzických hodů v Character Creation. Pokračovat?'))return;
  for(const key of changed)delete h.creation.attributeProof?.[key];
  if(changed.length){h.creation.status='in-progress';delete h.creation.completed[10];delete h.creation.completed[12];delete h.creation.completed[14];}
 }mutate(()=>{c.hmk={...h,attributes:a};syncCreationSkills(c.hmk,uuid)});return}if(f.id==='hmk-skill-form'){try{assertLegacyMutationAllowed(c)}catch(err){return alert(err.message)}if(combatInitiativeSequence)return alert('Během Initiative nelze měnit dovednosti mimo Combat průvodce.');if(!String(v.name||'').trim())return alert('Zadejte název dovednosti');const skill={id:uuid(),group:v.group,name:v.name.trim(),sb:v.sb===''?null:Number(v.sb),ml:v.ml===''?null:Number(v.ml)};if([skill.sb,skill.ml].some(n=>n!==null&&(!Number.isSafeInteger(n)||n<0||n>999)))return alert('Neplatné SB/ML');mutate(()=>{c.hmk={...h,skills:[...(h.skills||[]),skill]}});return}if(f.id==='hmk-injury-form'){if(combatInitiativeSequence)return alert('Během Initiative nelze mimo Combat zapisovat nové rány.');if(!String(v.location||'').trim())return alert('Zadejte lokalitu');mutate(()=>{c.hmk={...h,injuries:[...(h.injuries||[]),{id:uuid(),location:v.location,description:v.description||'',severity:v.severity||''}]}})}},true);
document.addEventListener('change',e=>{const id=e.target?.dataset?.encounterCharacter;if(!id)return;if(combatInitiativeSequence){e.target.checked=encounterSelection.has(id);return alert('Nejprve ukončete Initiative sekvenci; účastníky v jejím průběhu nelze tiše změnit.');}if(!data.characters.some(c=>c.id===id))return;if(!stagedEncounterSelection)stagedEncounterSelection=new Set(encounterSelection);if(e.target.checked)stagedEncounterSelection.add(id);else stagedEncounterSelection.delete(id);render()});
document.addEventListener('click',e=>{const t=e.target.closest('[data-remove-skill],[data-remove-injury]');if(!t)return;const c=character(selected);if(!c||!window.confirm('Odstranit tento záznam?'))return;if(t.dataset.removeSkill){try{assertLegacyMutationAllowed(c)}catch(err){return alert(err.message)}}const key=t.dataset.removeSkill?'skills':'injuries';const id=t.dataset.removeSkill||t.dataset.removeInjury;if(combatInitiativeSequence)return alert('Během Initiative se nemohou ručně mazat dovednosti ani zranění.');if(key==='injuries'&&c.hmk?.combatState?.wounds?.some(w=>w.id===id))return alert('Potvrzenou bojovou ránu nelze vymazat mimo pravidlové zotavení.');mutate(()=>{c.hmk=c.hmk||{};c.hmk[key]=(c.hmk[key]||[]).filter(x=>x.id!==id)})});

// v21: independent catalogue exchange. Never import character data or overwrite definitions.
// Canonical fingerprint: JSON object key order does not change a definition's identity.
// Array order is deliberately retained (weapon modes and layers may be ordered).
function canonicalCatalogValue(value){
 if(Array.isArray(value))return value.map(canonicalCatalogValue);
 if(value!==null&&typeof value==='object')return Object.fromEntries(Object.keys(value).sort().map(k=>[k,canonicalCatalogValue(value[k])]));
 return value;
}
function catalogFingerprint(x){return JSON.stringify(canonicalCatalogValue([x.category,x.name.trim().toLocaleLowerCase('cs'),x.description||'',x.source||'',x.properties]));}
function catalogNameConflicts(pending,existing){
 const names=new Map();
 for(const x of existing){const key=x.category+'|'+x.name.trim().toLocaleLowerCase('cs');if(!names.has(key))names.set(key,new Set());names.get(key).add(catalogFingerprint(x));}
 const conflicts=[];
 for(const x of pending){const key=x.category+'|'+x.name.trim().toLocaleLowerCase('cs');const variants=names.get(key);if(variants&&!variants.has(catalogFingerprint(x)))conflicts.push(x.name+' ('+x.category+')');if(!variants)names.set(key,new Set([catalogFingerprint(x)]));else variants.add(catalogFingerprint(x));}
 return conflicts;
}
// Validate the entire imported parameter tree before cloning or persisting it.
// The catalogue is data, never executable code. Reject excessive nesting and
// prototype-sensitive keys even though JSON.parse itself does not execute them.
function validateCatalogTree(value,depth=0,budget={nodes:0}){
 if(++budget.nodes>20000)throw Error('Příliš složitá struktura parametrů katalogu');
 if(depth>24)throw Error('Parametry katalogu jsou příliš hluboce vnořené');
 if(value===null||typeof value==='string'||typeof value==='boolean')return;
 if(typeof value==='number'&&Number.isFinite(value))return;
 if(Array.isArray(value)){
  if(value.length>10000)throw Error('Příliš dlouhý seznam v parametrech katalogu');
  for(const entry of value)validateCatalogTree(entry,depth+1,budget);
  return;
 }
 if(typeof value==='object'&&value!==null&&Object.getPrototypeOf(value)===Object.prototype){
  const keys=Object.keys(value);
  if(keys.length>2000)throw Error('Příliš mnoho polí v parametrech katalogu');
  for(const key of keys){
   if(['__proto__','constructor','prototype'].includes(key))throw Error('Nepovolený název pole v katalogu');
   validateCatalogTree(value[key],depth+1,budget);
  }
  return;
 }
 throw Error('Nepovolená hodnota v parametrech katalogu');
}
function prepareCatalogImport(pkg,existing){
 if(!pkg||pkg.format!=='hmk-equipment-catalog-v1'||!Array.isArray(pkg.items))throw Error('Neplatný formát katalogu');
 if(pkg.items.length>10000)throw Error('Katalog obsahuje příliš mnoho položek');
 const fingerprints=new Set(existing.map(catalogFingerprint));const pending=[];
 for(const x of pkg.items){
  if(!x||typeof x.name!=='string'||!x.name.trim()||x.name.length>250||!['weapon','shield','armor','other'].includes(x.category)||typeof x.description!=='string'||typeof x.source!=='string'||!x.properties||typeof x.properties!=='object'||Array.isArray(x.properties))throw Error('Katalog obsahuje neplatnou definici');
  // Reject unsafe/non-JSON nested values before touching the existing catalogue.
  validateCatalogTree(x.properties);
  if(JSON.stringify(x.properties).length>100000)throw Error('Parametry položky přesahují limit 100 kB');
  const fingerprint=catalogFingerprint(x);
  if(fingerprints.has(fingerprint))continue;
  fingerprints.add(fingerprint);
  pending.push({id:uuid(),name:x.name.trim(),category:x.category,description:x.description,source:x.source,properties:structuredClone(x.properties)});
 }
 return pending;
}

/** An observation is never guessed from distance or group membership. */
function guidedCohesionAssessmentFor(observerId,seq,participants,eventId,yn){
 const own=participants.find(p=>p.character.id===observerId);
 const cohort=own?.state.morale?.cohesion;
 if(!cohort)throw Error('Nejprve musíte doložit výchozí seznam spojenců Group Cohesion');
 const candidates=cohort.allyIds.filter(id=>{
  const p=participants.find(x=>x.character.id===id);
  return p&&(['INC','UNC','KIA'].includes(p.state.shock)||
   ['routed','withdrawing','catatonic'].includes(p.state.morale?.state));
 });
 if(!candidates.length)throw Error('Z doložených spojenců zatím nebyl nikdo prokazatelně vanquished');
 const noticedIds=[];
 for(const id of candidates){
  const p=participants.find(x=>x.character.id===id);
  if(cohort.knownVanquishedIds.includes(id))continue;
  const noticed=yn(`Všiml(a) si ${own.character.name}, že ${p.character.name} byl(a) vanquished?`);
  if(noticed===null)return null;
  if(noticed)noticedIds.push(id);
 }
 const fresh=new Set([...cohort.knownVanquishedIds,...noticedIds]);
 const threshold=Math.ceil(cohort.remainingAtThreshold.length/2);
 const newLost=cohort.remainingAtThreshold.filter(id=>fresh.has(id)).length;
 let roll=null,aberrance=null;
 if(cohort.remainingAtThreshold.length>0&&newLost>=threshold){
  const abe=window.prompt('Doložená Aberrance protivníka (0 pouze pokud je skutečně známo):','');
  if(abe===null)return null;
  if(!/^\d+$/.test(abe.trim())||Number(abe)>200)throw Error('Chybí doložená Aberrance');
  aberrance=Number(abe);
  const init=(own.character.hmk?.skills??[]).filter(x=>String(x.name??x.key??'').trim().toLowerCase()==='initiative');
  if(init.length!==1)throw Error('Chybí doložený Initiative ML');
  const fatigue=combatFatigueTotals(own.state).total;
  const raw=init[0].ml-fatigue-5*aberrance+(own.state.morale.state==='brave'?20:0);
  const entry=window.prompt(`${own.character.name}: Group Cohesion, fyzický Initiative d100; EML ${raw}. Zadejte 1–100:`, '');
  if(entry===null)return null;
  if(!/^\d+$/.test(entry.trim())||Number(entry)<1||Number(entry)>100)throw Error('Neplatný fyzický d100');
  roll=Number(entry);
 }
 return assessGuidedCohesion({sequence:seq,participants,observerId,noticedIds,eventId,roll,aberrance});
}
document.addEventListener('submit',e=>{
 if(e.target.id!=='hmk-guided-cohesion-due-form')return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  const seq=liveInitiativeSequence(),observerId=new FormData(e.target).get('observerId');
  if(!seq||!seq.order.includes(observerId))throw Error('Změnil se Initiative roster');
  const participants=seq.order.map(id=>({character:character(id),state:persistentStateOf(character(id))}));
  const due=groupCohesionDue(seq,participants);
  if(!due.some(x=>x.characterId===observerId))throw Error('Tato ztráta již není splatná');
  const yn=question=>{const v=window.prompt(question+' (ano/ne)','');
   if(v===null)return null;
   if(!['ano','ne'].includes(v.trim().toLowerCase()))throw Error('Zadejte ano/ne');
   return v.trim().toLowerCase()==='ano';};
  const eventId=uuid(),result=guidedCohesionAssessmentFor(observerId,seq,participants,eventId,yn);
  if(!result)return;
  const observer=character(observerId);
  commitGuidedTransition(result.sequence,()=>{
   synchronizeCombatInjuries(observer,result.state);
   data.journal.push({id:uuid(),characterId:observerId,createdAt:stamp(),title:`HMK Group Cohesion · kolo ${seq.round}`,
    body:`Povinné posouzení ztrát; ${result.triggered?'Morale '+result.result.slName:'bez prahového hodu'}.`,
    combatProof:{sourceEventId:eventId,round:seq.round,timelineId:seq.timelineId,actorId:observerId,
     actionKind:'group-cohesion-assessment',transition:structuredClone(result.event),
     physicalDice:structuredClone(result.event.details.physicalDice)}});
  });
  guidedAttackLastOutcome=`Group Cohesion: ${result.triggered?result.result.slName:'ztráty posouzeny'}; průvodce pokračuje.`;
  render();
 }catch(error){notice=error.message;render();}
},true);
// Resolve an already registered Special Morale debt before any new action.
// The user provides a physical d100; all rules and journal changes are atomic.
document.addEventListener('submit',e=>{
 if(e.target.id!=='hmk-guided-special-morale-due-form')return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  const v=Object.fromEntries(new FormData(e.target)),seq=liveInitiativeSequence();
  if(!seq)throw Error('Special Morale vyžaduje ověřenou Initiative');
  const c=character(v.characterId),ps=c?persistentStateOf(c):null;
  if(!c||!seq.order.includes(c.id)||!ps)throw Error('Special Morale: neplatný účastník');
  if(!/^\d+$/.test(String(v.roll))||!/^\d+$/.test(String(v.aberrance)))
   throw Error('Special Morale: zadejte skutečný d100 a doloženou Aberrance');
  const first=dueEncounterEvents(seq,combatSequenceStates())[0];
  if(first?.characterId!==c.id||first.type!=='special-morale')
   throw Error('Existuje dřívější povinná událost; Special Morale nelze přeskočit ani předběhnout');
  const eventId=uuid();
  const result=resolveSpecialMorale({sequence:seq,character:c,state:ps,
   roll:Number(v.roll),aberrance:Number(v.aberrance),eventId});
  commitGuidedTransition(result.sequence,()=>{
   if(data.journal.some(j=>j.combatProof?.sourceEventId===eventId))throw Error('Duplicitní Special Morale');
   synchronizeCombatInjuries(c,result.state);
   data.journal.push({id:uuid(),characterId:c.id,createdAt:stamp(),
    title:`HMK Special Morale · kolo ${seq.round}`,
    body:`${result.event.details.reason}: Initiative EML ${result.event.details.rawEML}, fyzický d100 ${v.roll} → ${result.result.slName}; stav ${result.state.morale.state}.`,
    combatProof:{sourceEventId:eventId,round:seq.round,timelineId:seq.timelineId,actorId:c.id,
     actionKind:'special-morale-resolution',transition:structuredClone(result.event),
     physicalDice:structuredClone(result.event.details.physicalDice)}});
  });
  guidedAttackLastOutcome=`${c.name}: Special Morale ${result.result.slName}; další povinný krok automaticky pokračuje.`;
  render();
 }catch(err){notice=err.message;render();}
},true);
// v93.89: sequential, physical-dice-only Melee/Missile→wound guided interface.
document.addEventListener('submit',e=>{
 const f=e.target;
 if(!['hmk-guided-hit-start-form','hmk-guided-hit-die-form','hmk-guided-hit-choice-form','hmk-guided-hit-duration-form','hmk-guided-hit-path-form','hmk-guided-hit-displacement-form'].includes(f.id))return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  const v=Object.fromEntries(new FormData(f));
  if(f.id==='hmk-guided-hit-start-form'){
   const linkedIntent=pendingCombatActionHandoff?confirmSheetCombatAction(pendingCombatActionHandoff,{
    kind:v.kind,actorId:v.attackerId,targetId:v.defenderId,sequence:liveInitiativeSequence(),
    signature:guidedAttackLiveSignature(v.attackerId,v.defenderId)}):null;
   if(guidedAttackSession||guidedMountedSession||guidedTurnSession||guidedDeclaredSession||guidedSpatialSession||guidedTraumaSession||guidedBloodSession||guidedRecoverySession||g04Actions.hasActive())throw Error('Nejprve uzavřete rozpracovanou bojovou událost');
   if(v.kind==='cohesion-register'||v.kind==='cohesion-assess'){
    const seq=liveInitiativeSequence();
    if(!seq)throw Error('Group Cohesion vyžaduje aktivní Initiative a úplný roster');
    const observer=character(v.attackerId);
    if(!observer||!seq.order.includes(observer.id))throw Error('Vyberte skutečného pozorovatele ze střetnutí');
    const participants=seq.order.map(id=>({character:character(id),state:persistentStateOf(character(id))}));
    const state=persistentStateOf(observer),id=uuid();
    const yn=question=>{const answer=window.prompt(question+' (ano/ne)','');
     if(answer===null)return null;
     if(!['ano','ne'].includes(answer.trim().toLowerCase()))throw Error('Musíte zadat přesně ano/ne');
     return answer.trim().toLowerCase()==='ano';};
    let outcome;
    if(v.kind==='cohesion-register'){
     if(firstGuidedMandatoryDue(selectedEncounterCharacters()))throw Error('Nejprve vyřešte všechny splatné povinné následky');
     const allyIds=[];
     for(const p of participants){if(p.character.id===observer.id)continue;
      const allied=yn(p.character.name+': byl na začátku této skupiny skutečným spojencem '+observer.name+'?');
      if(allied===null)return;if(allied)allyIds.push(p.character.id);
     }
     outcome=registerGuidedCohesion({sequence:seq,participants,observerId:observer.id,allyIds,eventId:id});
    }else{
     outcome=guidedCohesionAssessmentFor(observer.id,seq,participants,id,yn);
     if(!outcome)return;
    }
    commitGuidedTransition(outcome.sequence,()=>{
     if(data.journal.some(j=>j.combatProof?.sourceEventId===id))throw Error('Duplicitní Group Cohesion');
     synchronizeCombatInjuries(observer,outcome.state);
     data.journal.push({id:uuid(),characterId:observer.id,createdAt:stamp(),
      title:`HMK Group Cohesion · kolo ${seq.round}`,
      body:outcome.event.type==='group-cohesion-roster'?'Doložena výchozí skupina spojenců':
       `Ztráty spojenců: práh ${outcome.event.details.threshold}, Morale test ${outcome.triggered?'ANO ('+outcome.result?.slName+')':'NE'}.`,
      combatProof:{sourceEventId:id,round:seq.round,timelineId:seq.timelineId,actorId:observer.id,
       actionKind:outcome.event.type,transition:structuredClone(outcome.event),
       physicalDice:structuredClone(outcome.event.details.physicalDice)}});
    });
    guidedAttackLastOutcome=`${observer.name}: Group Cohesion ${outcome.triggered?'Morale '+outcome.result.slName:'bez dalšího hodu'}; uloženo.`;
    render();return;
   }
   if(v.kind==='surrender-release'){
    const seq=liveInitiativeSequence();
    if(!seq)throw Error('Ukončení kapitulace vyžaduje Initiative');
    if(seq.pendingEndTurnAction||seq.interruptActiveId||dueEncounterEvents(seq,combatSequenceStates()).length)
     throw Error('Nejprve uzavřete všechny dřívější splatné následky a již probíhající přerušení');
    const target=character(v.attackerId);
    if(!target||!seq.order.includes(target.id))throw Error('Vyberte skutečného účastníka');
    if(persistentStateOf(target).morale?.surrender?.active!==true)
     throw Error('Postava nemá aktivní doloženou kapitulaci');
    const reason=window.prompt('Co se ve skutečnosti změnilo, že kapitulace skončila? (nejméně 5 znaků)','');
    if(reason===null)return;
    if(!window.confirm('GM potvrzuje faktické ukončení kapitulace; Morale State se tím automaticky nemění?'))return;
    const eventId=uuid(),outcome=recordConfirmedSurrenderRelease({state:persistentStateOf(target),
     round:seq.round,timelineId:seq.timelineId,eventId,reason,gmConfirmed:true});
    const next=validateEncounterSequence(seq);
    next.log.push({round:seq.round,type:'morale-surrender-released',actorId:target.id,eventId});
    commitGuidedTransition(next,()=>{
     if(data.journal.some(j=>j.combatProof?.sourceEventId===eventId))throw Error('Duplicitní zrušení kapitulace');
     synchronizeCombatInjuries(target,outcome.state);
     data.journal.push({id:uuid(),characterId:target.id,createdAt:stamp(),
      title:`HMK kapitulace ukončena · kolo ${seq.round}`,
      body:`GM doložil konec kapitulace: ${reason.trim()}; Morale State zůstává ${outcome.state.morale.state}.`,
      combatProof:{sourceEventId:eventId,round:seq.round,timelineId:seq.timelineId,
       actorId:target.id,actionKind:'morale-surrender-released',transition:structuredClone(outcome.state.events.at(-1)),physicalDice:{rolls:[]}}});
    });
    guidedAttackLastOutcome=`${target.name}: konec kapitulace byl uložen bez automatické změny Morale.`;
    render();return;
   }
   if(v.kind==='vanquished-ruling'){
    const seq=liveInitiativeSequence();
    if(!seq)throw Error('Vanquished: chybí Initiative a úplný roster');
    if(firstGuidedMandatoryDue(selectedEncounterCharacters()))throw Error('Nejprve vyřešte povinné následky');
    const target=character(v.attackerId);
    if(!target||!seq.order.includes(target.id))throw Error('Zvolte postiženou postavu v poli Útočník');
    const answers=['paralysis','entanglement','sleep','enthralment','grievous-functional-loss','disarmed-against-armed','other'];
    const category=window.prompt('Skutečná příčina funkčního vyřazení:\n'+answers.join(' / '),'');
    if(category===null)return;
    if(!answers.includes(category.trim()))throw Error('Neznámá doložená příčina Vanquished');
    const reason=window.prompt('Popište ověřený stav neschopnosti či jeho skončení (nejméně 5 znaků)','');
    if(reason===null)return;
    const flag=window.prompt('Je teď postava funkčně Vanquished? Zadejte ano (vznik) / ne (ukončení)','');
    if(flag===null)return;
    if(!['ano','ne'].includes(flag.trim().toLowerCase()))throw Error('Zadejte ano/ne');
    const active=flag.trim().toLowerCase()==='ano';
    if(!window.confirm('GM potvrzuje, že skutečný výsledek neschopnosti pohybu či agresivní akce je doložen. U disarmament GM určil, že jde o funkční Vanquished.'))return;
    const participants=seq.order.map(id=>({character:character(id),state:persistentStateOf(character(id))}));
    const eventId=uuid(),outcome=recordGuidedFunctionalVanquished({sequence:seq,participants,
     targetId:target.id,active,category:category.trim(),reason,eventId,gmConfirmed:true});
    commitGuidedTransition(outcome.sequence,()=>{
     synchronizeCombatInjuries(target,outcome.state);
     data.journal.push({id:uuid(),characterId:target.id,createdAt:stamp(),
      title:`HMK Vanquished · kolo ${seq.round}`,
      body:`GM potvrdil: ${active?'funkčně vyřazen':'funkční vyřazení skončilo'}; ${reason}.`,
      combatProof:{sourceEventId:eventId,round:seq.round,timelineId:seq.timelineId,actorId:target.id,
       actionKind:'gm-functional-vanquished',transition:structuredClone(outcome.event),physicalDice:{rolls:[]}}});
    });
    guidedAttackLastOutcome=`${target.name}: Vanquished ${active?'ANO':'NE'}; skupinové ztráty jsou nyní kontrolovány.`;
    render();return;
   }
   if(v.kind==='special-morale'){
    const seq=liveInitiativeSequence();
    if(!seq)throw Error('Special Morale vyžaduje běžící Initiative a úplný roster');
    if(firstGuidedMandatoryDue(selectedEncounterCharacters()))throw Error('Nejdřív dokončete splatné povinné následky');
    const participants=seq.order.map(id=>({character:character(id),state:persistentStateOf(character(id))}));
    const yn=q=>{const answer=window.prompt(q+' (ano/ne)','');
     if(answer===null)return null;
     if(!['ano','ne'].includes(answer.trim().toLowerCase()))throw Error('Odpovězte ano/ne');
     return answer.trim().toLowerCase()==='ano';};
    const options=Object.entries(SPECIAL_MORALE_KINDS).map(([key,label])=>key+' = '+label).join('\n');
    const rawKind=window.prompt('Jaká skutečná událost spouští Special Morale?\n'+options,'');
    if(rawKind===null)return;
    const kind=rawKind.trim();
    if(!Object.hasOwn(SPECIAL_MORALE_KINDS,kind))throw Error('Vyberte přesný druh Special Morale');
    const incidentRef=window.prompt('Stabilní ID JEDNÉ konkrétní události (např. loss-captain-01); při opakování se duplicitní událost odmítne','');
    if(incidentRef===null)return;
    const description=window.prompt('Popište konkrétní skutečně nastalou událost, nikoli výsledek Morale','');
    if(description===null)return;
    const facts={};
    if(kind==='leader-vanquished'){
     const names=participants.map(p=>p.character.id+' = '+p.character.name).join('\n');
     const leaderId=window.prompt('Který velitel byl skutečně vyřazen? Zadejte ID:\n'+names,'');
     if(leaderId===null)return;
     facts.leaderId=leaderId.trim();
     const leader=participants.find(p=>p.character.id===facts.leaderId);
     if(!leader)throw Error('Neznámá postava velitele');
     const mechanical=['INC','UNC','KIA'].includes(leader.state.shock)||
      ['catatonic','routed','withdrawing'].includes(leader.state.morale?.state);
     if(!mechanical){
      const confirmed=yn('Velitel je podle konkrétního pravidlového následku fakticky vyřazen, ačkoli není mechanicky INC/UNC/KIA/Routed?');
      if(confirmed===null)return;
      facts.gmFunctionalVanquished=confirmed;
      if(confirmed){const ruling=window.prompt('Jaké doložené znehybnění/účinek velitele způsobilo vyřazení?','');
       if(ruling===null)return;facts.gmRuling=ruling.trim();}
     }
    }
    if(kind==='greatly-outnumbered'){
     const count=(label,min)=>{const v=window.prompt(label,'');if(v===null)return null;
      if(!/^\d+$/.test(v.trim())||Number(v)<min||Number(v)>1000)throw Error('Neplatný doložený počet');return Number(v);};
     facts.armedEnemies=count('Skutečný počet protivníků',1);if(facts.armedEnemies===null)return;
     facts.alliesAbleToFight=count('Skutečný počet schopných spojenců',0);if(facts.alliesAbleToFight===null)return;
     facts.gmGreatlyOutnumbered=yn('GM podle okolností potvrdil VÝRAZNOU početní převahu?');
     if(facts.gmGreatlyOutnumbered===null)return;
    }
    if(kind==='disarmed-against-armed'){
     facts.disarmed=yn('Jsou příslušní pozorovatelé skutečně odzbrojeni?');if(facts.disarmed===null)return;
     facts.armedOpposition=yn('Čelí skutečně ozbrojeným protivníkům?');if(facts.armedOpposition===null)return;
    }
    const observerIds=[];
    for(const p of participants){
     if(['INC','UNC','KIA'].includes(p.state.shock)||p.state.morale?.state==='catatonic')continue;
     const aware=yn(p.character.name+': tato událost skutečně spustila Morale a postava ji vnímala?');
     if(aware===null)return;if(aware)observerIds.push(p.character.id);
    }
    const confirmed=yn(`Potvrdit ${observerIds.length} samostatných povinných Morale testů po JEDNÉ doložené události?`);
    if(confirmed!==true)return;
    const eventId=uuid(),outcome=registerSpecialMorale({sequence:seq,participants,observerIds,kind,
     incidentRef,description,facts,eventId,gmConfirmed:true});
    commitGuidedTransition(outcome.sequence,()=>{
     if(data.journal.some(j=>j.combatProof?.sourceEventId===eventId))throw Error('Duplicitní Special Morale');
     for(const [id,after] of Object.entries(outcome.states))synchronizeCombatInjuries(character(id),after);
     for(const id of observerIds)data.journal.push({id:uuid(),characterId:id,createdAt:stamp(),
      title:`HMK Special Morale · doložená událost · kolo ${seq.round}`,
      body:`${description}. Povinný fyzický Initiative d100 bude zadán jednotlivě.`,
      combatProof:{sourceEventId:eventId,round:seq.round,timelineId:seq.timelineId,actorId:id,
       actionKind:'special-morale-declaration',incidentKey:outcome.incidentKey,triggerKind:kind,
       physicalDice:{rolls:[]}}});
    });
    guidedAttackLastOutcome=`Special Morale: ${observerIds.length} postav; průvodce nyní vyžádá jejich jednotlivé fyzické hody.`;
    render();return;
   }
   if(v.kind==='free-action'){
    const seq=liveInitiativeSequence(),actor=character(v.attackerId);
    if(!seq||!actor||!encounterSelection.has(actor.id)||currentEncounterActor(seq)!==actor.id)
     throw Error('Vyberte právě jednajícího účastníka Initiative');
    if(!encounterFreeActionAvailable(seq,actor.id,combatSequenceStates()))
     throw Error('Volná akce již proběhla nebo nezačíná bezprostředně na začátku tahu');
    if(guidedAttackSession||guidedMountedSession||guidedTurnSession||guidedDeclaredSession||guidedSpatialSession||guidedTraumaSession||guidedBloodSession||guidedRecoverySession)
     throw Error('Nejprve dokončete rozpracovanou pravidlovou posloupnost');
    if(firstGuidedMandatoryDue(selectedEncounterCharacters()))
     throw Error('Nejdříve vyřešte povinný bojový následek');
    const choice=window.prompt('Volná akce HMK str.161: draw = zbraň, pocket = kapsa, step = 5 ft, open = dveře/truhla, command = příkaz spojencům, intimidate = Command vs Initiative (skutečné d100)', 'draw');
    if(choice===null)return;
    const kind=({draw:'draw-weapon',pocket:'ready-pocket-item',step:'five-foot-step',open:'open-unlocked-object',command:'command-allies',intimidate:'intimidate-foe'})[choice.trim().toLowerCase()];
    if(!kind)throw Error('Vyberte draw, pocket, step, open, command nebo intimidate');
    if(kind==='intimidate-foe'){
     // Combat free-action Intimidation is opposed Command vs Initiative,
     // NOT an automatic Morale change. Both d100 are actual physical rolls.
     const candidates=seq.order.filter(id=>id!==actor.id);
     const answer=window.prompt('ID skutečně zastrašovaného protivníka:\n'+candidates.map(id=>id+' – '+(character(id)?.name||id)).join('\n'),candidates[0]||'');
     if(answer===null)return;
     const targetId=answer.trim(),target=character(targetId);
     if(!target||!candidates.includes(targetId))throw Error('Neplatný účastník pro Intimidation');
     const uniqueSkill=(c,name)=>{
      const found=(c.hmk?.skills||[]).filter(x=>String(x.name||'').trim().toLowerCase()===name);
      if(found.length!==1||!Number.isSafeInteger(found[0].ml)||found[0].ml<0||found[0].ml>200)
       throw Error(c.name+': nutná jednoznačně doložená dovednost '+name+' ML (0–200)');
      return found[0].ml;
     };
     const commandML=uniqueSkill(actor,'command'),initiativeML=uniqueSkill(target,'initiative');
     const threat=window.prompt('Skutečná vyslovená nebo přímo předvedená hrozba (HMK pp.67,137–138)','');
     if(threat===null)return;
     const foe=window.confirm('GM: tato postava je skutečný protivník a zastrašování je právě teď vhodná bezprostřední volná akce?');
     if(!foe)return;
     const heard=window.confirm('GM: cíl hrozbu skutečně viděl nebo slyšel a je schopen ji vnímat?');
     if(!heard)return;
     const parseModifier=(label)=>{
      const raw=window.prompt(label+' (celé číslo −100 až +100; 0 = žádný potvrzený modifikátor)','0');
      if(raw===null)return null;
      if(!/^[+-]?\d+$/.test(raw.trim())||Math.abs(Number(raw))>100)throw Error('Neplatný GM modifikátor Intimidation');
      return Number(raw);
     };
     const commandModifier=parseModifier('GM: všechny další výslovně doložené modifikátory Command');if(commandModifier===null)return;
     const initiativeModifier=parseModifier('GM: všechny další výslovně doložené modifikátory Initiative cíle');if(initiativeModifier===null)return;
     const d100=(who)=>{
      const raw=window.prompt(who+': hoď skutečný d100 a zadej 1–100','');
      if(raw===null)return null;
      if(!/^\d+$/.test(raw.trim())||Number(raw)<1||Number(raw)>100)throw Error('Nutný skutečný platný d100');
      return Number(raw);
     };
     const commandRoll=d100(actor.name+' · Command');if(commandRoll===null)return;
     const initiativeRoll=d100(target.name+' · Initiative');if(initiativeRoll===null)return;
     const fatigueA=combatFatigueTotals(persistentStateOf(actor)).total;
     const fatigueB=combatFatigueTotals(persistentStateOf(target)).total;
     const tieD10=[];
     for(let attempts=0;attempts<30;attempts++){
      const trial=resolveGuidedIntimidationOpposition({commandML,initiativeML,commandFatigue:fatigueA,initiativeFatigue:fatigueB,
       commandModifier,initiativeModifier,commandRoll,initiativeRoll,tieD10});
      if(!trial.needsTieD10)break;
      const rawA=window.prompt(actor.name+': úplná remíza – hoď skutečný rozhodovací d10','');if(rawA===null)return;
      const rawB=window.prompt(target.name+': úplná remíza – hoď skutečný rozhodovací d10','');if(rawB===null)return;
      if(!/^\d+$/.test(rawA.trim())||!/^\d+$/.test(rawB.trim())||Number(rawA)<1||Number(rawA)>10||Number(rawB)<1||Number(rawB)>10)
       throw Error('Rozhodovací kostky musí být skutečné d10 1–10');
      tieD10.push({command:Number(rawA),initiative:Number(rawB)});
     }
     const id=uuid();
     const outcome=prepareGuidedIntimidation({id,sequence:seq,states:combatSequenceStates(),actorId:actor.id,targetId,
      spokenThreat:threat,commandML,initiativeML,commandModifier,initiativeModifier,commandRoll,initiativeRoll,tieD10,
      foeConfirmed:foe,heardOrSawConfirmed:heard,immediateConfirmed:true});
     commitGuidedTransition(outcome.sequence,()=>{
      if(data.journal.some(j=>j.combatProof?.sourceEventId===id))throw Error('Duplicitní Intimidation');
      const body=actor.name+' → '+target.name+': Intimidation '+(outcome.proof.result.winner==='command'?'uspěla':'neuspěla')+
       ' ('+outcome.proof.result.stars+' hvězdiček). Hrozba: '+outcome.proof.spokenThreat+'. Automatická změna Morale: žádná.';
      for(const participantId of [actor.id,target.id])data.journal.push({id:uuid(),characterId:participantId,createdAt:stamp(),
       title:'HMK Intimidation · kolo '+seq.round,body,combatProof:outcome.proof});
     });
     guidedAttackLastOutcome='Intimidation: '+(outcome.proof.result.winner==='command'?'přesvědčivější Command':'odolal cíl')+
      ', '+outcome.proof.result.stars+' hvězdiček. Žádné Morale nebylo automaticky přiřazeno.';
     render();return;
    }
    let itemId=null,hand=null,accessibleConfirmed=false,sourceConfirmed=false,destination=null,effectiveMove=null;
    let objectId=null,objectKind=null,objectClosedConfirmed=false,objectUnlockedConfirmed=false,objectInReachConfirmed=false,doorSegment=null;
    let recipientIds=null,spokenWords=null,recipientsHearConfirmed=false,recipientsAlliesConfirmed=false;
    if(kind==='open-unlocked-object'){
     const raw=window.prompt('Stabilní ID skutečných dveří/truhly (stejné ID při dalších akcích):','');
     if(raw===null)return;objectId=raw.trim();
     const typ=window.prompt('Druh objektu: door / trunk','door');
     if(typ===null)return;objectKind=typ.trim().toLowerCase();
     objectClosedConfirmed=window.confirm('Je tento KONKRÉTNÍ objekt právě zavřený?');
     if(!objectClosedConfirmed)return;
     objectUnlockedConfirmed=window.confirm('Je tento objekt odemčený (HMK str.161)?');
     if(!objectUnlockedConfirmed)return;
     objectInReachConfirmed=window.confirm('Je tento objekt ve skutečném dosahu postavy?');
     if(!objectInReachConfirmed)return;
     if(objectKind==='door'&&!seq.spatialBarriers?.some(b=>b.id===objectId)){
      const raw=window.prompt('Doložte skutečný úsek otevřených dveří v mapě: x1,y1:x2,y2 (ft).\n'+
       'Bez geometrie nelze zajistit návaznost na pohyb.','');
      if(raw===null)return;
      const bars=parseSpatialBarrierSegments('door:'+objectId+':'+raw.trim());
      doorSegment={from:bars[0].from,to:bars[0].to};
     }
    }else if(kind==='command-allies'){
     const raw=window.prompt('ID skutečných příjemců příkazu, oddělená čárkou:\n'+
      seq.order.filter(id=>id!==actor.id).map(id=>`${id} – ${character(id)?.name||id}`).join('\n'),'');
     if(raw===null)return;
     recipientIds=raw.split(',').map(x=>x.trim()).filter(Boolean);
     spokenWords=window.prompt('Skutečný krátký vyslovený příkaz (žádný automatický Morale nebo Command efekt):','');
     if(spokenWords===null)return;
     recipientsAlliesConfirmed=window.confirm('GM potvrzuje, že všichni jmenovaní příjemci jsou skutečnými spojenci velící postavy.');
     if(!recipientsAlliesConfirmed)return;
     recipientsHearConfirmed=window.confirm('GM potvrzuje, že všichni uvedení spojenci příkaz opravdu slyšeli. Příkaz sám NEMĚNÍ jejich stav.');
     if(!recipientsHearConfirmed)return;
    }else if(kind==='five-foot-step'){
     effectiveMove=liveSpatialProfile(actor).effectiveMove;
     const rawX=window.prompt('Skutečná výsledná souřadnice X (ft) podle uložené mapy','');
     if(rawX===null)return;
     const rawY=window.prompt('Skutečná výsledná souřadnice Y (ft) podle uložené mapy','');
     if(rawY===null)return;
     if(!rawX.trim()||!rawY.trim()||!Number.isFinite(Number(rawX))||!Number.isFinite(Number(rawY)))
      throw Error('Souřadnice musí být skutečně doložená čísla');
     destination={x:Number(rawX),y:Number(rawY)};
    }else{
     const accessible=data.inventory.filter(x=>x.characterId===actor.id&&x.slot==='carried'&&x.quantity===1&&
      !x.destroyed&&x.gearStowage!=='backpack'&&x.snapshot?.category===(kind==='draw-weapon'?'weapon':'other'));
     if(!accessible.length)throw Error('Není doložený samostatně nesený vhodný předmět mimo batoh');
     const selection=window.prompt('Zadejte přesné ID předmětu z inventáře:\n'+accessible.map(x=>`${x.id} – ${x.snapshot.name}`).join('\n'),accessible[0].id);
     if(selection===null)return;
     itemId=selection.trim();
     const h=window.prompt('Cílová skutečně volná ruka: main_hand nebo off_hand','main_hand');
     if(h===null)return;
     hand=h.trim();
     sourceConfirmed=window.confirm(kind==='draw-weapon'?'Je zbraň skutečně v pochvě nebo za pásem a připravená k tasení?':'Je drobný předmět skutečně v kapse a připravený k vytažení?');
     if(!sourceConfirmed)return;
     accessibleConfirmed=window.confirm('Je předmět okamžitě dostupný bez hledání v batohu a cílová ruka je skutečně volná?');
     if(!accessibleConfirmed)return;
    }
    const id=uuid();
    const result=prepareGuidedFreeAction({id,sequence:seq,states:combatSequenceStates(),
     inventory:data.inventory,actorId:actor.id,kind,itemId,hand,accessibleConfirmed,sourceConfirmed,
     destination,effectiveMove,objectId,objectKind,objectClosedConfirmed,objectUnlockedConfirmed,
     objectInReachConfirmed,doorSegment,recipientIds,spokenWords,recipientsHearConfirmed,recipientsAlliesConfirmed});
    commitGuidedTransition(result.sequence,()=>{
     if(data.journal.some(j=>j.combatProof?.sourceEventId===id))throw Error('Duplicitní volná akce');
     data.inventory=result.inventory;
     data.journal.push({id:uuid(),characterId:actor.id,createdAt:stamp(),
      title:`HMK volná akce · kolo ${seq.round}`,
      body:`${actor.name}: ${kind}${itemId?' · '+itemId:''}${objectId?' · '+objectId:''}${recipientIds?' · příjemci '+recipientIds.join(', '):''}${destination?' · ('+destination.x+', '+destination.y+') ft':''}`,
      combatProof:result.proof});
    });
    guidedAttackLastOutcome=`${actor.name}: ${kind} byl uložen jako jediná volná akce. Nyní může následovat povolená hlavní 1-turn akce.`;
    render();return;
   }
   if(v.kind==='rally'){
    if(guidedAttackSession||guidedMountedSession||guidedTurnSession||guidedDeclaredSession||guidedSpatialSession||guidedTraumaSession||guidedBloodSession||guidedRecoverySession)
     throw Error('Dokončete nejprve rozpracovanou bojovou událost');
    const seq=liveInitiativeSequence();
    if(!seq)throw Error('Rally vyžaduje skutečně běžící Initiative scheduler');
    if(firstGuidedMandatoryDue(selectedEncounterCharacters()))throw Error('Nejprve vyřešte povinné následky');
    const leader=character(v.attackerId);
    if(!leader||!encounterSelection.has(leader.id))throw Error('Vyberte velitele z aktuálního střetnutí');
    const yn=question=>{const raw=window.prompt(question+' (ano/ne)','');
     if(raw===null)return null;
     if(!['ano','ne'].includes(raw.trim().toLowerCase()))throw Error('Pravidlovou skutečnost je nutné doložit ano/ne');
     return raw.trim().toLowerCase()==='ano';};
    if(!encounterFreeActionAvailable(seq,leader.id,combatSequenceStates()))
     throw Error('Rally: volná akce již byla použita nebo tah nepokračuje bezprostředně od svého začátku');
    const participants=seq.order.map(id=>({character:character(id),state:persistentStateOf(character(id))}));
    const routed=participants.filter(p=>p.character.id!==leader.id&&
     ['routed','withdrawing'].includes(p.state.morale?.state));
    const assessments=[];
    for(const p of routed){
     const id=p.character.id,name=p.character.name;
     const allied=yn(name+': patří ke spojencům velitele?');if(allied===null)return;
     const a={id,allied};
     if(allied){
      a.leaderAware=yn(name+': ví velitel o tomto spojenci a jeho poloze?');if(a.leaderAware===null)return;
      if(!a.leaderAware){assessments.push(a);continue;}
      a.earshot=yn(name+': je skutečně v rozpoznatelném doslechu Rally?');if(a.earshot===null)return;
      a.understands=yn(name+': rozumí velitelovu příkazu?');if(a.understands===null)return;
      if(a.earshot&&a.understands){
       const existingLock=p.state.morale?.rallyLockout;
       if(existingLock&&existingLock.timelineId!==seq.timelineId){
        const elapsed=window.prompt(name+': kolik CELÝCH minut skutečně uplynulo od zákazu Rally z minulého střetnutí?','');
        if(elapsed===null)return;
        if(!/^\d+$/.test(elapsed.trim()))throw Error('Uvedený čas Rally musí být doložené celé minuty');
        a.elapsedLockoutMinutes=Number(elapsed);
       }
       a.perceptionCertain=yn(name+': je vnímání velitelova příkazu bez pochybností?');
       if(a.perceptionCertain===null)return;
       if(!a.perceptionCertain){
        const die=window.prompt(name+': vnímání je nejisté. Zadejte skutečný Awareness d100','');
        if(die===null)return;
        if(!/^\d+$/.test(die.trim())||Number(die)<1||Number(die)>100)
         throw Error('Awareness vyžaduje fyzický d100 v rozsahu 1–100');
        a.awarenessRoll=Number(die);
       }
      }
     }
     assessments.push(a);
    }
    const prepared=guidedRallyReadiness({leader,participants,sequence:seq,assessments});
    const raw=window.prompt(`${leader.name}: Rally = Command ML ${prepared.commandML} + Initiative Secondary ${prepared.secondary>=0?'+':''}${prepared.secondary} − Fatigue ${prepared.fatigue} = EML ${prepared.rawEML}. Zadejte JEDEN skutečný Command d100 (1–100).`, '');
    if(raw===null)return;
    if(!/^\d+$/.test(raw.trim())||Number(raw)<1||Number(raw)>100)
     throw Error('Rally vyžaduje skutečný d100 v rozsahu 1–100');
    const result=resolveGuidedRally({context:prepared,roll:Number(raw),participants,
     sequence:seq,eventId:uuid()});
    commitGuidedTransition(result.sequence,()=>{
     if(data.journal.some(j=>j.combatProof?.sourceEventId===result.event.id))
      throw Error('Duplicitní Rally');
     for(const [id,state] of Object.entries(result.states))synchronizeCombatInjuries(character(id),state);
     const listeners=new Set([leader.id,...Object.keys(result.states)]);
     for(const id of listeners)data.journal.push({id:uuid(),characterId:id,createdAt:stamp(),
      title:`HMK Rally · kolo ${seq.round}`,body:`${leader.name}: Rally ${result.sl}; `+
       `zasaženo ${Object.keys(result.states).length} spojenců, Command EML ${prepared.rawEML}.`,
      combatProof:{sourceEventId:result.event.id,round:seq.round,timelineId:seq.timelineId,
       actorId:leader.id,actionKind:'rally',transition:structuredClone(result.event),
       physicalDice:structuredClone(result.event.details.physicalDice)}});
    });
    guidedAttackLastOutcome=`${leader.name}: Rally ${result.sl}, ${Object.keys(result.states).length} spojenců; další povinné Reaction naplánovány podle výsledku.`;
    render();return;
   }
   if(v.kind==='morale-reaction'){
    const patient=character(v.attackerId);
    if(!patient||!encounterSelection.has(patient.id))throw Error('Vyberte postavu s Routed / Withdrawing v poli Útočník');
    if(firstGuidedMandatoryDue(selectedEncounterCharacters()))throw Error('Nejdříve dokončete splatný povinný následek');
    const ps=persistentStateOf(patient),kind=ps.morale?.state;
    if(!['routed','withdrawing'].includes(kind))throw Error('Postava není Routed ani Withdrawing');
    const confirm=(question)=>{const answer=window.prompt(question+' (ano/ne)','');
     if(answer===null)return null;const value=answer.trim().toLowerCase();
     if(!['ano','ne'].includes(value))throw Error('Podmínku je nutné doložit ano/ne');
     return value==='ano';};
    const condition=confirm(kind==='routed'?'Je postava opravdu v bezpečí MIMO dohled protivníků?':
     'Je postava skutečně NEohrožená?');
    if(condition===null)return;
    const actual=window.prompt('Kolik celých bezpečných minut skutečně uplynulo od počátku tohoto období?','');
    if(actual===null)return;
    if(!/^\d+$/.test(actual.trim()))throw Error('Čas bezpečí musí být celé číslo, nikoli odhad či prázdný údaj');
    const minutes=Number(actual),safeOutOfLOS=kind==='routed'&&condition,
     unthreatened=kind==='withdrawing'&&condition;
    const context=guidedMoraleReactionReadiness({character:patient,state:ps,round:combatClock.round,
     timelineId:combatInjuryTimelineId,elapsedSafeMinutes:minutes,safeOutOfLOS,unthreatened});
    const answer=window.prompt(`${patient.name}: Initiative EML ${context.eml}. Zadejte skutečný fyzický d100 (1–100)`, '');
    if(answer===null)return;
    if(!/^\d+$/.test(answer.trim()))throw Error('Zadejte skutečnou celou hodnotu d100');
    const eventId=uuid(),result=resolveGuidedMoraleReaction({character:patient,state:ps,
     round:combatClock.round,timelineId:combatInjuryTimelineId,eventId,
     elapsedSafeMinutes:minutes,safeOutOfLOS,unthreatened,roll:Number(answer)});
    const applyMoraleReaction=()=>{
     if(data.journal.some(j=>j.combatProof?.sourceEventId===eventId))throw Error('Duplicitní Morale Reaction');
     const current=character(patient.id);
     if(!current||JSON.stringify(persistentStateOf(current))!==JSON.stringify(ps))
      throw Error('Morale se před potvrzením změnila; událost musí být znovu vyhodnocena');
     synchronizeCombatInjuries(current,result.state);
     data.journal.push({id:uuid(),characterId:patient.id,createdAt:stamp(),
      title:`HMK Morale Reaction · kolo ${combatClock.round}`,
      body:`${patient.name}: ${context.kind} → ${result.state.morale.state}; Initiative EML ${context.eml}.`,
      combatProof:{sourceEventId:eventId,timelineId:combatInjuryTimelineId,round:combatClock.round,
       actorId:patient.id,actionKind:'guided-morale-reaction',physicalDice:structuredClone(result.event.details.physicalDice),
       transition:structuredClone(result.event)}});
    };
    // Both the Morale transition and its physical-dice proof are committed
    // under the same Initiative checkpoint, with rollback on storage failure.
    if(combatInitiativeSequence)commitGuidedTransition(liveInitiativeSequence(),applyMoraleReaction);
    else if(!mutate(applyMoraleReaction))throw Error('Reakce nebyla trvale uložena, žádný stav se nezměnil');
    guidedAttackLastOutcome=`${patient.name}: Reaction ${context.kind} → ${result.state.morale.state}. Fyzický d100 uložen.`;
    render();return;
   }
   if(v.kind==='trauma-course'){
    // This is a timed medical follow-up, never an extra attack/turn action.
    const patient=character(v.attackerId);
    if(!patient||!encounterSelection.has(patient.id))throw Error('Zvolte léčenou postavu v poli Útočník');
    const readiness=guidedTraumaCourseReadiness({state:persistentStateOf(patient),character:patient});
    if(!readiness.available)throw Error('Postava nemá aktivní Extended Shock ani Coma Course');
    const exact=(label,min,max)=>{
     const val=window.prompt(label,'');if(val===null)return null;
     if(!/^\d+$/.test(val.trim())||!Number.isSafeInteger(Number(val))||Number(val)<min||Number(val)>max)
      throw Error('Neplatný ověřený čas či bonus: '+label);
     return Number(val);
    };
    const elapsedHoursSinceOnset=readiness.kind==='extended-shock'?exact(`Kolik celých hodin skutečně uplynulo od začátku Extended Shock? Další Course vyžaduje ${readiness.nextHours} hodin.`,4,100000):null;
    if(readiness.kind==='extended-shock'&&elapsedHoursSinceOnset===null)return;
    const daysElapsed=readiness.kind==='coma'?exact(`Kolik dní od předchozího Coma Course skutečně uplynulo? Očekává se ${readiness.nextDays}.`,1,10000):null;
    if(readiness.kind==='coma'&&daysElapsed===null)return;
    const physicianStars=readiness.kind==='extended-shock'?exact('Ověřený počet hvězd nejvyšší Physician SV (0 pokud neproběhla pomoc léčitele)',0,10):null;
    if(readiness.kind==='extended-shock'&&physicianStars===null)return;
    const arcaneBonus=exact('Ověřený bonus Arcane Recovery (0 pokud se nepoužívá)',0,100);
    if(arcaneBonus===null)return;
    let restfulShelter=null;
    if(readiness.kind==='coma'){
     const answer=window.prompt('Je prostředí pro zotavení klidné a chráněné? Zadejte ano nebo ne','');
     if(answer===null)return;
     if(!['ano','ne'].includes(answer.trim().toLowerCase()))throw Error('Pro Coma je nutné výslovně ano/ne');
     restfulShelter=answer.trim().toLowerCase()==='ano';
    }
    if(!window.confirm('Potvrzujete skutečné uplynutí požadovaného času a správnost podmínek Course podle HMK p.179?'))return;
    guidedTraumaSession=createGuidedTraumaCourse({state:persistentStateOf(patient),character:patient,
     eventId:uuid(),round:combatClock.round,timelineId:combatInjuryTimelineId,kind:readiness.kind,
     elapsedHoursSinceOnset,daysElapsed,physicianStars,arcaneBonus,restfulShelter,timeConfirmed:true});
    guidedAttackLastOutcome=`${patient.name}: ${readiness.kind} · Healing Base ${readiness.healingBase}, EML ${guidedTraumaSession.context.rawEML}. Zadejte skutečný Course hod.`;
    writeGuidedDraft();render();return;
   }
   // The same scheduler that completes a turn determines its lawful actions.
   // A forced Mishap Pass, Confused, Catatonic or unresolved end-turn Shock
   // cannot be bypassed by selecting an attack from the start form.
   if(combatInitiativeSequence&&v.kind!=='turn-action'){
    const seq=liveInitiativeSequence(),policy=guidedTurnChoices(seq,combatSequenceStates());
    if(seq.freeActionTurn?.kind==='five-foot-step'&&['spatial','mishap-recovery'].includes(v.kind))
     throw Error('Pětistopý volný krok se nesmí kombinovat s Move, Evade ani Charge (HMK str.161)');
    const legal=policy.kind==='player-choice'?policy.choices:[];
    const requested=v.kind==='mishap-recovery'?['move','grope']:v.kind==='spatial'?['move','evade','charge']:
     ['melee','press','trip','grab','missile'].includes(v.kind)?['attack']:
     v.kind==='mounted-control'?['other']:[];
    if(!requested.some(x=>legal.includes(x)))
     throw Error('Initiative nyní nepovoluje tuto akci: '+
      (policy.events?.map(x=>x.type).join(', ')||'povinný Pass, změněná Alertness nebo neschopnost postavy'));
   }
   if(v.kind==='mishap-recovery'&&liveInitiativeSequence()?.freeActionTurn?.kind==='five-foot-step')
    throw Error('Po volném pětistopém kroku nelze v témže tahu provést vstávání s Move');
   if(v.kind==='mishap-recovery'){
    const seq=liveInitiativeSequence(),states=combatSequenceStates(),actorId=currentEncounterActor(seq),c=character(actorId);
    if(!c)throw Error('Chybí právě jednající postava');
    const posture=states[actorId]?.posture??{};
    const available=[...(posture.prone?['stand']:[]),...(posture.dropPending?['retrieve']:[])];
    if(!available.length)throw Error('Postava neleží ani nemá evidovaný upuštěný předmět');
    const kind=available.length===1?available[0]:window.prompt('Zvolte pravidlovou akci: stand nebo retrieve',available[0]);
    if(kind===null)return;
    if(!available.includes(kind))throw Error('Vyberte pouze skutečně dostupný následný Move nebo Grope');
    const allowed=guidedTurnChoices(seq,states);
    if(allowed.kind!=='player-choice'||!allowed.choices.includes(kind==='stand'?'move':'grope'))
     throw Error('Tato akce není aktuálně povolena kvůli Initiative nebo povinnému následku');
    const profile=kind==='stand'?liveSpatialProfile(c):null;
    const battlefield=kind==='retrieve'?observedSpatialBattlefield(v,actorId):
     // Standing in place does not require a map. A player may supply a complete
     // observed map at the START to continue the same Move after standing.
     selectedEncounterCharacters().every(u=>v[`map_${u.id}_x`]!==''&&v[`map_${u.id}_y`]!=='')?
      observedSpatialBattlefield(v,actorId):null;
    guidedRecoverySession=createGuidedMishapRecovery({id:uuid(),sequence:seq,states,character:c,
     inventory:data.inventory,kind,effectiveMove:profile?.effectiveMove??null,battlefield,
     droppedItemPosition:kind==='retrieve'?{x:v.drop_x===''?null:Number(v.drop_x),y:v.drop_y===''?null:Number(v.drop_y)}:null});
    guidedAttackLastOutcome=kind==='stand'?`Vstávání stojí ${states[actorId].shock==='STN'?20:10} ft z Move; pokud zbývá pohyb a je doložená mapa, lze pokračovat ve STEJNÉM tahu.`:'Grope spotřebuje tah; při ohrožení bude vyžádán Melee d100.';
    continueGuidedRecovery();return;
   }
   if(v.kind==='spatial'){
    if(liveInitiativeSequence()?.freeActionTurn?.kind==='five-foot-step')
     throw Error('Pětistopý volný krok se nesmí kombinovat s Move, Evade ani Charge');
    guidedSpatialSession=createLiveSpatialChoice(v);
    guidedSpatialWitness=spatialLiveWitness(guidedSpatialSession.actorId);
    guidedAttackLastOutcome='Prostorová akce: systém sám zkontroluje Engagement Zones a skutečný Move.';render();return;
   }
   if(v.kind==='turn-action'){
    const seq=liveInitiativeSequence(),states=combatSequenceStates();
    const witness=JSON.stringify({seq,states});
    guidedTurnSession=createGuidedTurnAction({id:uuid(),sequence:seq,states});
    guidedTurnWitness=witness;continueGuidedTurn();return;
   }
   if(v.kind==='mounted-control'){
    const rider=character(v.attackerId),mount=character(v.mountId);
    if(!rider||!mount||rider.id===mount.id||!encounterSelection.has(rider.id)||!encounterSelection.has(mount.id))
     throw Error('Vyberte skutečného jezdce a odlišné jízdní zvíře ze střetnutí');
    const active=liveInitiativeSequence();
    if(!active||currentEncounterActor(active)!==rider.id)
     throw Error('Control lze zahájit jen na aktivním IR jezdce');
    if(!encounterFreeActionAvailable(active,rider.id,combatSequenceStates()))
     throw Error('Control vyžaduje první dosud nepoužitou volnou akci');
    if(dueEncounterEvents(active,combatSequenceStates()).length)
     throw Error('Nejdříve vyřešte splatné události');
    if(data.journal.some(j=>j.combatProof?.actionKind==='mounted-control'&&
     j.combatProof?.timelineId===combatInjuryTimelineId&&j.combatProof?.round===combatClock.round&&
     j.combatProof?.actorId===rider.id&&j.combatProof?.mountId===mount.id))
     throw Error('Tento jezdec již vyhodnotil Control pro stejné zvíře v tomto kole');
    const witness=guidedAttackLiveSignature(rider.id,mount.id),token=uuid();
    guidedMountedSession=createGuidedMountedControl({id:uuid(),timelineId:combatInjuryTimelineId,
     round:combatClock.round,rider,mount,state:persistentStateOf(rider),sourceSignature:token});
    guidedMountedWitness=witness;continueGuidedMounted();return;
   }
   const attacker=character(v.attackerId),defender=character(v.defenderId);
   if(!attacker||!defender||attacker.id===defender.id||!encounterSelection.has(attacker.id)||!encounterSelection.has(defender.id))throw Error('Vyberte dva různé účastníky střetnutí');
   if(combatInitiativeSequence){
    const active=liveInitiativeSequence();
    requireInitialCrossbowShot(active,{actorId:attacker.id,weaponId:v.attackerWeaponId,attackKind:v.kind});
    assertScheduledHitCanCommit(active,attacker.id,combatSequenceStates());
    const due=dueEncounterEvents(active,combatSequenceStates());
    if(due.length)throw Error('Dříve musí být dokončena splatná událost: '+JSON.stringify(due[0]));
   }
   for(const participant of selectedEncounterCharacters()){
    const due=guidedMandatoryEvents({state:persistentStateOf(participant),characterId:participant.id,
     round:combatClock.round,actorId:combatClock.actorId,turnEnded:false,timelineId:combatInjuryTimelineId});
    if(due.length)throw Error('Před útokem je splatná událost '+participant.name+': '+due[0].label);
   }
   // With an active Initiative, the confirmed attack token is authoritative.
   // A pre-combat Load, free action or other journal entry is NOT a strike
   // and must not block the first physical attack (especially p.161).
   if(!combatInitiativeSequence&&data.journal.some(j=>j.combatProof?.timelineId===combatInjuryTimelineId&&
    j.combatProof?.round===combatClock.round&&j.combatProof?.actorId===attacker.id&&
    ['attack','charge'].includes(j.combatProof?.actionKind)))
    throw Error('Tato postava již v tomto kole provedla zaznamenaný útok');
   const helpless=verifiedDeadlyHelplessReason(persistentStateOf(defender));
   if(helpless&&['melee','press','trip','grab'].includes(v.kind))throw Error('HMK str.191: bezbranný cíl musí volit Ignore a automaticky utrpí čtyřhvězdičkový CS. Vyberte Deadly Melee, nikoli běžný útok.');
   const signature=guidedAttackLiveSignature(attacker.id,defender.id);
   const token=uuid();
   const common={id:uuid(),timelineId:combatInjuryTimelineId,round:combatClock.round,
    attacker,defender,inventory:data.inventory,sourceSignature:token,direction:v.direction,
    opponents:Number(v.opponents),aimZN:Number(v.aimZN)};
   let result;
   if(['melee','press','trip','grab'].includes(v.kind))result=createLiveGuidedMelee({...common,
    attackerWeaponId:v.attackerWeaponId,defenderWeaponId:v.defenderWeaponId,
    attackerSkillId:v.attackerSkillId,defenderSkillId:v.defenderSkillId,
    attackerUsedArms:v.attackerUsedArms,defenderUsedArms:v.defenderUsedArms,
    attackerFoes:Number(v.attackerFoes),defenderFoes:Number(v.defenderFoes)});
   else if(v.kind==='deadly'){
    const deadlyAim=v.deadlyCalled==='yes'?verifiedDeadlyAim(liveInitiativeSequence(),combatSequenceStates(),{
     actorId:attacker.id,targetId:defender.id,location:v.deadlyLocation,side:v.deadlySide||null}):null;
    if(v.deadlyCalled!=='yes'&&(v.deadlyLocation||v.deadlySide))throw Error('Bez zvolené koncentrace nevyplňujte cílenou lokaci ani stranu');
    if(!helpless)throw Error('Deadly Melee: cíl nemá doložený helpless stav. Je třeba nejprve zaznamenat skutečný stav postavy.');
    result=createLiveGuidedDeadlyMelee({...common,attackerWeaponId:v.attackerWeaponId,
     attackerSkillId:v.attackerSkillId,attackerUsedArms:v.attackerUsedArms,
     attackerFoes:Number(v.attackerFoes),gmReachConfirmed:v.deadlyReachConfirmed==='yes',deadlyAim});
   }else if(v.kind==='missile'){
    if(combatInitiativeSequence)assertFumebombLineOfSight({journal:data.journal,sequence:liveInitiativeSequence(),campaignId:campaignKey(data.campaignClock),fromId:attacker.id,toId:defender.id});
    // A selected bow/crossbow/sling is NOT proof of a loaded projectile.
    // The loaded marker comes only from completed and durable Span/Load.
    const selectedWeapon=data.inventory.find(x=>x.id===v.attackerWeaponId&&x.characterId===attacker.id);
    const missileType=liveMissileWeaponType(selectedWeapon);
    let loadedProjectile=null;
    if(['bow','crossbow','sling'].includes(missileType)){
     if(!combatInitiativeSequence)throw Error('Nabití střelné zbraně vyžaduje aktivní doloženou Initiative a dokončený Load');
     loadedProjectile=requireLoadedMissile({sequence:liveInitiativeSequence(),inventory:data.inventory,
      actorId:attacker.id,weaponId:v.attackerWeaponId}).loaded;
    }
    const aimBonus=combatInitiativeSequence?verifiedMissileAimBonus({sequence:liveInitiativeSequence(),
     inventory:data.inventory,actorId:attacker.id,weaponId:v.attackerWeaponId}):0;
    const evasion=combatInitiativeSequence?liveSpatialEvade(liveInitiativeSequence(),
     {targetId:defender.id,targetState:persistentStateOf(defender)}):{active:false};
    if(v.targetMovement==='evading'&&!evasion.active)throw Error('Evade musí být doložená aktivní událostí cíle, nelze ji pouze vybrat');
    let crossbowBasis=null;
    if(missileType==='crossbow'){
     const selected=window.prompt('HMK str.163: střelec volí kušový test: ml (Archery ML) nebo sb3 (Archery SB × 3). Žádný hod zatím neprovádějte.','ml');
     if(selected===null)return;
     crossbowBasis=selected.trim().toLowerCase();
     if(!['ml','sb3'].includes(crossbowBasis))throw Error('Kuše: vyberte přesně ml nebo sb3');
    }
    result=createLiveGuidedMissile({...common,loadedProjectile,aimBonus,crossbowBasis,
    weaponId:v.attackerWeaponId,skillId:v.attackerSkillId,attackerUsedArms:v.attackerUsedArms,distance:Number(v.distance),
    targetMovement:evasion.active?'evading':v.targetMovement,effectiveDodgeIndex:evasion.active?evasion.index:null,
    targetCount:Number(v.targetCount),nearbyTargetCount:Number(v.nearbyTargetCount),
    potentialTargets:selectedEncounterCharacters(),
    windforce:Number(v.windforce),crosswind:v.crosswind==='yes',movingShooter:v.movingShooter==='yes'});
   }else throw Error('Neznámý typ útoku');
   if(['press','trip','grab'].includes(v.kind)){
    guidedDeclaredSession=createGuidedDeclaredManeuver({id:uuid(),sourceSession:result.session,technique:v.kind,
     attacker,defender,inventory:data.inventory,targetState:persistentStateOf(defender),
     sourceSignature:token,aimZN:Number(v.aimZN),attackerUsedArms:v.attackerUsedArms,defenderUsedArms:v.defenderUsedArms});guidedDeclaredWitness=signature;guidedAttackToken=token;guidedAttackAudit=result.preflight;
   }else{guidedAttackSession=result.session;guidedAttackWitness=signature;guidedAttackToken=token;guidedAttackAudit=result.preflight;}
   if(linkedIntent){
    if(guidedDeclaredSession)guidedDeclaredSession={...guidedDeclaredSession,sourceActionHandoff:linkedIntent};
    else guidedAttackSession={...guidedAttackSession,sourceActionHandoff:linkedIntent};
    pendingCombatActionHandoff=null;
   }
   guidedAttackLastOutcome=(v.kind==='deadly'?'HMK str.191: Ignore + four-star CS bez Attack/Defence d100; soustředění 1 kolo dovoluje zvolenou lokaci bez ZD/LD, následně Impact/Injury/Shock. ':'Ověřené podklady: ')+JSON.stringify(result.preflight);
   if(guidedDeclaredSession){continueGuidedDeclared();return;}
  }else{
   if(guidedBloodSession){
    if(f.id!=='hmk-guided-hit-die-form')throw Error('Blood Stoppage nyní vyžaduje fyzický hod');
    guidedBloodSession=submitGuidedBloodStoppageDie(guidedBloodSession,v.roll);
    continueGuidedBlood();return;
   }
   if(guidedTraumaSession){
    if(f.id!=='hmk-guided-hit-die-form')throw Error('Trauma Course nyní vyžaduje fyzický hod');
    const c=character(guidedTraumaSession.characterId);
    if(!c||JSON.stringify(persistentStateOf(c))!==guidedTraumaSession.stateWitness||
     JSON.stringify(c.hmk)!==guidedTraumaSession.characterWitness)
     throw Error('Trauma Course: postava nebo pravidlový stav se během hodu změnily');
    guidedTraumaSession=submitGuidedTraumaCourseDie(guidedTraumaSession,v.roll);
    continueGuidedTrauma();return;
   }
   if(guidedRecoverySession){
    const s=guidedRecoverySession,c=character(s.actorId),req=guidedMishapRecoveryRequirement(s);
    if(s.sequenceWitness!==JSON.stringify(liveInitiativeSequence())||
     s.statesWitness!==JSON.stringify(combatSequenceStates())||
     s.inventoryWitness!==JSON.stringify(data.inventory)||
     s.characterWitness!==JSON.stringify(c))throw Error('Zotavení po Mishap má zastaralé podklady');
    if(req.kind==='choice'&&f.id==='hmk-guided-hit-choice-form')
     guidedRecoverySession=req.id==='recovery-stand-continuation'?
      chooseGuidedRecoveryStandContinuation(s,v.decision):
      req.id==='recovery-mishap-technique'?
       chooseGuidedRecoveryMishapTechnique(s,v.decision,{character:c,state:persistentStateOf(c)}):
       chooseGuidedRecoveryHand(s,v.decision,{character:c,state:persistentStateOf(c),inventory:data.inventory});
    else if(req.kind==='point'&&f.id==='hmk-guided-hit-path-form'){
     if(!/^\d+$/.test(v.difficultSources||'')||Number(v.difficultSources)>8)
      throw Error('Přesně doložené Difficult Movement zdroje musí být 0–8');
     const pattern=/^\s*-?\d+(?:\.\d+)?\s*,\s*-?\d+(?:\.\d+)?\s*$/;
     const parts=String(v.route||'').split(';').map(x=>x.trim());
     if(!parts.length||parts.length>98||parts.some(x=>!pattern.test(x)))
      throw Error('Trasa po vstávání: zadejte doložené souřadnice x,y oddělené středníkem');
     const actor=s.battlefield?.units?.find(u=>u.id===s.actorId);
     if(!actor)throw Error('Pro pokračování pohybu chybí doložená výchozí poloha');
     const path=[{x:actor.x,y:actor.y},...parts.map(part=>{const [x,y]=part.split(',').map(Number);return {x,y};})];
     guidedRecoverySession=setGuidedRecoveryStandPath(s,{path,difficultSources:Number(v.difficultSources)});
    }else if(req.kind==='die'&&f.id==='hmk-guided-hit-die-form')
     guidedRecoverySession=submitGuidedRecoveryDie(s,v.roll,{character:c,state:persistentStateOf(c)});
    else throw Error('Očekává se doložená volba, trasa nebo fyzický hod');
    continueGuidedRecovery();return;
   }
   if(guidedSpatialSession){
    const seq=liveInitiativeSequence(),states=combatSequenceStates();
    if(spatialLiveWitness(guidedSpatialSession.actorId)!==guidedSpatialWitness)throw Error('Stav, výbava, pořadí tahů nebo mapa se změnily');
    guidedSpatialSession=f.id==='hmk-guided-hit-stumble-technique-form'?chooseLiveSpatialStumbleTechnique(guidedSpatialSession,v):f.id==='hmk-guided-hit-die-form'?submitLiveSpatialDie(guidedSpatialSession,v.roll):f.id==='hmk-guided-hit-path-form'?setLiveSpatialPath(guidedSpatialSession,v):f.id==='hmk-guided-hit-stumble-stop-form'?setLiveSpatialStumbleStop(guidedSpatialSession,v):chooseLiveSpatial(guidedSpatialSession,v.decision);
    continueGuidedSpatial();return;
   }
   if(guidedDeclaredSession){
    const a=guidedDeclaredSession;
    if(guidedAttackLiveSignature(a.attackerId,a.defenderId)!==guidedDeclaredWitness)
     throw Error('Účastníci nebo výbava se v průběhu deklarovaného manévru změnili');
    if(f.id==='hmk-guided-hit-displacement-form'){
     const units=selectedEncounterCharacters().map(c=>({id:c.id,
      x:Number(v[`displace_${c.id}_x`]),y:Number(v[`displace_${c.id}_y`])}));
     for(const c of selectedEncounterCharacters())if(v[`displace_${c.id}_x`]===''||v[`displace_${c.id}_y`]==='')
      throw Error('Chybí přesná poloha '+c.name);
     if(v.displacementX===''||v.displacementY==='')throw Error('Chybí přesná cílová poloha manévru');
     guidedDeclaredSession=submitGuidedDeclaredDisplacement(a,{units,
      destination:{x:Number(v.displacementX),y:Number(v.displacementY)},clearPath:v.clearPath==='yes'});
    }else{
     if(f.id==='hmk-guided-hit-choice-form'&&a.phase==='melee'&&
        guidedDeclaredRequirement(a).id==='defence'&&combatInitiativeSequence)
      requireConcentrationCompatibleDefence(liveInitiativeSequence(),{defenderId:a.defenderId,defence:v.decision});
     guidedDeclaredSession=f.id==='hmk-guided-hit-die-form'?submitGuidedDeclaredDie(a,v.roll):
      f.id==='hmk-guided-hit-duration-form'?submitGuidedDeclaredFact(a,v.duration):chooseGuidedDeclared(a,v.decision);
    }
    continueGuidedDeclared();return;
   }
   if(guidedTurnSession){
    const seq=liveInitiativeSequence(),states=combatSequenceStates();
    if(JSON.stringify({seq,states})!==guidedTurnWitness)throw Error('Stav tahu se během volby změnil');
    if(f.id==='hmk-guided-hit-choice-form'&&guidedTurnRequirement(guidedTurnSession).kind==='choice'&&
       v.decision==='concentrate-start'){
     const previous=guidedTurnSession,previousWitness=guidedTurnWitness;
     // This choice is intercepted BEFORE generic concentration starts, and
     // only when the player really selected Concentrate (not on every turn).
     guidedTurnSession=null;guidedTurnWitness=null;
     try{
      const outcome=offerGuidedMissilePreparation(seq,states,currentEncounterActor(seq));
      if(outcome==='handled')return;
      guidedTurnSession=previous;guidedTurnWitness=previousWitness;
      if(outcome==='cancelled'){render();return;}
     }catch(error){guidedTurnSession=previous;guidedTurnWitness=previousWitness;throw error;}
    }
    guidedTurnSession=f.id==='hmk-guided-hit-duration-form'?enterGuidedTurnDuration(guidedTurnSession,v.duration):chooseGuidedTurnAction(guidedTurnSession,v.decision);
    continueGuidedTurn();return;
   }
   if(guidedMountedSession){
    const a=guidedMountedSession;
    if(guidedAttackLiveSignature(a.riderId,a.mountId)!==guidedMountedWitness)
     throw Error('Mounted Control už není aktuální');
    guidedMountedSession=f.id==='hmk-guided-hit-die-form'?submitGuidedMountedDie(a,v.roll):chooseGuidedMounted(a,v.decision);
    continueGuidedMounted();return;
   }
   if(!guidedAttackSession)throw Error('Není rozpracovaný řízený útok');
   const a=guidedAttackSession;
   if(guidedAttackLiveSignature(a.attackerId,a.defenderId)!==guidedAttackWitness)throw Error('Údaje postavy nebo inventáře se změnily; výpočet je neaktuální');
   if(guidedAttackCandidate){
    const req=guidedAttackNextRequirement();
    if(guidedAttackMishapSession){
     if(f.id==='hmk-guided-hit-choice-form')guidedAttackMishapSession=chooseGuidedMeleeMishapTechnique(guidedAttackMishapSession,v.decision);
     else if(f.id==='hmk-guided-hit-die-form')guidedAttackMishapSession=submitGuidedMeleeMishapDie(guidedAttackMishapSession,v.roll);
     else throw Error('Pro Melee Mishap je povolena jen správná volba nebo fyzický hod');
    }else if(guidedAttackFreePressSession){
     if(f.id==='hmk-guided-hit-choice-form')guidedAttackFreePressSession=chooseGuidedFreePress(guidedAttackFreePressSession,v.decision);
     else if(f.id==='hmk-guided-hit-displacement-form'){
      const units=selectedEncounterCharacters().map(c=>({id:c.id,x:Number(v[`displace_${c.id}_x`]),y:Number(v[`displace_${c.id}_y`])}));
      for(const c of selectedEncounterCharacters())if(v[`displace_${c.id}_x`]===''||v[`displace_${c.id}_y`]==='')
       throw Error('Chybí doložená poloha '+c.name);
      if(v.displacementX===''||v.displacementY==='')throw Error('Chybí cílová poloha Free Press');
      guidedAttackFreePressSession=submitGuidedFreePressDisplacement(guidedAttackFreePressSession,{units,
       destination:{x:Number(v.displacementX),y:Number(v.displacementY)},clearPath:v.clearPath==='yes'});
     }else guidedAttackFreePressSession=submitGuidedFreePressDie(guidedAttackFreePressSession,v.roll);
    }else if(f.id==='hmk-guided-hit-duration-form'&&req.kind==='input'&&req.id==='injury-morale-aberrance'){
     if(!/^\d+$/.test(String(v.duration).trim())||Number(v.duration)>200)
      throw Error('Skutečná Aberrance musí být doložené celé číslo 0–200');
     const first=guidedAttackImmediateEvents()[0];
     const wound=guidedAttackCandidate.state.wounds.find(w=>w.id===first?.id&&w.moralePending);
     if(!wound||first.kind!=='injury-morale'||wound.moraleThreatId!==guidedAttackSession.hitSession.strikerId)
      throw Error('Změnil se zdroj povinného Morale');
     wound.moraleThreatABE=Number(v.duration); // draft only; durable with the hit
    }else if(f.id==='hmk-guided-hit-choice-form'){
     if(req.kind!=='choice'||req.id!=='aftermath-technique'||!req.choices.some(x=>x.value===v.decision))throw Error('Nedovolená hráčská volba');
     guidedAttackAftermathTechnique=v.decision;
    }else{
     if(req.kind!=='die'||!guidedAttackAftermath)throw Error('Není vyžádána další kostka');
     guidedAttackAftermath=submitGuidedMandatoryDie(guidedAttackAftermath,v.roll);
    }
   }else{
    // HMK p.160: when the unified Melee wizard offers a defence, it must
    // enforce the same concentration rule as the old Melee preview.
    if(f.id==='hmk-guided-hit-choice-form'&&a.kind==='melee'&&
       guidedAttackRequirement(a).id==='defence'&&combatInitiativeSequence)
     requireConcentrationCompatibleDefence(liveInitiativeSequence(),{defenderId:a.defenderId,defence:v.decision});
    guidedAttackSession=f.id==='hmk-guided-hit-die-form'?submitGuidedAttackDie(a,v.roll):
     f.id==='hmk-guided-hit-duration-form'?submitGuidedAttackFact(a,v.duration):chooseGuidedAttack(a,v.decision);
   }
  }
  continueGuidedAttack();
 }catch(error){guidedAttackLastOutcome='Řízený zásah: '+error.message;render();}
},true);
document.addEventListener('click',e=>{
 const button=e.target.closest?.('[data-action="hmk-guided-attack-cancel"]');
 if(!button)return;
 e.preventDefault();pendingCombatActionHandoff=null;clearGuidedAttack();guidedMountedSession=null;guidedMountedWitness=null;guidedTurnSession=null;guidedTurnWitness=null;guidedDeclaredSession=null;guidedDeclaredWitness=null;guidedSpatialSession=null;guidedSpatialWitness=null;guidedTraumaSession=null;guidedBloodSession=null;guidedRecoverySession=null;guidedChargeContext=null;guidedAttackLastOutcome='Rozpracovaná bojová událost zrušena – žádný zápis neproběhl.';render();
},true);

render();
// If a valid wizard was recovered at its automatic terminal step, resume the
// deterministic continuation; no physical die is invented or re-rolled.
try{
 if(guidedRecoverySession&&guidedMishapRecoveryRequirement(guidedRecoverySession).kind==='complete')continueGuidedRecovery();
 else if(guidedBloodSession&&guidedBloodStoppageRequirement(guidedBloodSession).kind==='automatic')continueGuidedBlood();
 else if(guidedTraumaSession&&guidedTraumaCourseRequirement(guidedTraumaSession).kind==='automatic')continueGuidedTrauma();
 else if(guidedDeclaredSession&&guidedDeclaredRequirement(guidedDeclaredSession).kind==='complete')continueGuidedDeclared();
 else if(guidedSpatialSession&&guidedSpatialRequirement(guidedSpatialSession).kind==='complete')continueGuidedSpatial();
 else if(guidedMountedSession&&guidedMountedRequirement(guidedMountedSession).kind==='complete')continueGuidedMounted();
 else if(guidedTurnSession&&guidedTurnRequirement(guidedTurnSession).kind==='complete')continueGuidedTurn();
 else if(guidedAttackSession&&guidedAttackNextRequirement().kind==='complete')continueGuidedAttack();
}catch(e){guidedAttackLastOutcome='Bezpečné obnovení průvodce vyžaduje další krok: '+e.message;render();}

// Show the deterministic result immediately as the GM types physical dice.
// The same resolver runs AGAIN during the persistent mutation: UI updates
// alone are never trusted as evidence and no die is generated by the app.
// One source-linked explanatory dialog for every Character Creation field.
// Pure UI: never modifies the creation state or generates random dice.
document.addEventListener('click',event=>{
 const btn=event.target?.closest?.('[data-hmk-rule-help]');if(!btn)return;
 event.preventDefault();event.stopImmediatePropagation();
 const modal=document.getElementById('hmk-rule-dialog');if(!modal)return;
 const field=btn.closest('label')?.querySelector('[name]');
 const selectedOption=field?.tagName==='SELECT'?field.selectedOptions?.[0]?.textContent:'';
 const step=Number(btn.dataset.hmkRuleStep);
 const liveCharacter=character(selected);
 const wizardForm=btn.closest('#creation-step-form');
 const current=(name)=>wizardForm?.elements?.namedItem(name)?.value||'';
 const liveHelpValues={...(liveCharacter?.hmk?.creation?.values??{})};
 for(const key of ['familyWeaponcrafterType','familyMartialChoice','familyVariantChoice',
  'familyRitualChoice','familyScriptChoice','familySecondScriptChoice',
  'occupationLanguageChoice','occupationScriptChoice','occupationRitualChoice',
  'nativeRitualChoice','moralityChoice','pvarChantryId']){
  const value=current(key);if(value)liveHelpValues[key]=value;
 }
 const previewCharacter={...liveCharacter,
  occupation:current('occupation')||liveCharacter?.occupation,
  hmk:{...(liveCharacter?.hmk??{}),
   creation:{...(liveCharacter?.hmk?.creation??{}),values:liveHelpValues},
   folk:current('folk')||liveCharacter?.hmk?.folk,
   ageGroup:current('ageGroup')||liveCharacter?.hmk?.ageGroup,
   familyOccupation:current('familyOccupation')||liveCharacter?.hmk?.familyOccupation,
   birthRegion:current('birthRegion')||liveCharacter?.hmk?.birthRegion,
   socialClass:current('socialClass')||liveCharacter?.hmk?.socialClass,
   society:current('society')||liveCharacter?.hmk?.society}};
 const fieldName=btn.dataset.hmkRuleHelp;
 // DP is interpreted for the actual Skill chosen immediately beside it.
 const chosen=fieldName==='skillDP'?current('skillName'):(field?.value??'');
 const stage=SKILL_STAGES[creationOf(liveCharacter).skillStage]??null;
 const note=fieldRuleNote(step,fieldName,previewCharacter,chosen,stage);
 const title=btn.dataset.hmkRuleTitle||'Pravidla pro tuto volbu';
 modal.querySelector('#hmk-rule-dialog-title').textContent=title+(selectedOption&&chosen?' · '+selectedOption:'');
 modal.querySelector('#hmk-rule-dialog-page').textContent='HMK v1.2 · tištěná str. '+note.page;
 modal.querySelector('#hmk-rule-dialog-effect').textContent=note.effect;
 modal.querySelector('#hmk-rule-dialog-dice').textContent=note.dice;
 modal.querySelector('#hmk-rule-dialog-original').textContent=note.excerpt.length?'HMK v1.2 – '+note.quoteScope+': “'+note.excerpt.join('”  “')+'”':'Tato položka nemá v tištěných pravidlech samostatný doslovný popis.';
 modal.querySelector('#hmk-rule-dialog-context').textContent=note.context||'Nejprve určete příslušné vstupní hodnoty postavy.';
 modal.querySelector('#hmk-rule-dialog-status').textContent=note.hasExcerpt?'Doslovný anglický výňatek ze zdrojové strany je oddělen od českého výkladu a údajů konkrétní postavy.':note.verified?'K této ovládací položce není v příručce samostatná věta; nepřidávejte vlastní pravidla.':'Přesné speciální pravidlo zde není doloženo; potřebné výjimky nelze domýšlet.';
 if(typeof modal.showModal==='function')modal.showModal();else modal.setAttribute('open','');
},true);

document.addEventListener('input',event=>{
 const form=event.target?.closest?.('#creation-step-form');if(!form)return;
 const original=character(selected);if(!original)return;
 const result=form.querySelector('[data-creation-roll-preview]');
 const name=event.target?.name;
 // Switching a prerequisite removes the active old roll in this form.
 if(name==='birthRegion'||name==='venariveRoll'){
  for(const field of ['regionRoll','birthplace','society','nativeLanguageRoll','regionSubRoll','regionDialectRoll','nativeLanguageChoice','regionTribeRoll','regionCommunityChoice','regionDialectChoice','regionAzeriDialectChoice']){
   const el=form.elements.namedItem(field);if(el)el.value='';
  }
 }
 if(name==='regionRoll'||name==='birthplace'){for(const field of ['nativeLanguageRoll','regionSubRoll','regionDialectRoll','nativeLanguageChoice','regionTribeRoll','regionCommunityChoice','regionDialectChoice','regionAzeriDialectChoice']){const el=form.elements.namedItem(field);if(el)el.value='';}}
 if(name==='classDie'){const el=form.elements.namedItem('classRoll');if(el)el.value='';}
 if(name==='subsistence'){
  for(const field of ['parentOccupationRoll','parentOccupationSubRoll','parentOccupationSpecialRoll','parentOccupationConvocationRoll','familyOccupation','familyWeaponcrafterType','familyMartialChoice','familyVariantChoice']){
   const el=form.elements.namedItem(field);if(el)el.value='';
  }
 }
 try{refreshCreationChoiceUI(form,original)}catch(err){if(result)result.textContent='Nabídku nelze obnovit: '+err.message}
 const values=Object.fromEntries(new FormData(form));
 try{
  const computed=creationChoicesFromPhysicalDice(original,creationOf(original).step,values);
  for(const [name,value] of Object.entries(computed)){
   const target=Array.from(form.elements).find(el=>el.name===name);
   if(target){
    if(target.tagName==='SELECT'&&!Array.from(target.options).some(o=>o.value===String(value)))target.add(new Option(String(value),String(value)));
    target.value=String(value);target.dataset.creationDerived='true'
   }
  }
  refreshCreationChoiceUI(form,original);
  if(result)result.textContent=Object.entries(computed).length?'Vypočteno z fyzického hodu: '+Object.entries(computed).map(([k,v])=>k+' → '+v).join(' · '):'Bez aktivního losování: použije se vaše ruční volba.';
 }catch(err){if(result)result.textContent='Zatím nelze vyhodnotit: '+err.message}
},true);

/** Optional Appendix III: persist real choices/rolls without changing the
 * mandatory 14-step validation. Never synthesize a physical die in manual
 * mode; a later automatic candidate may roll an otherwise unset value. */
const APPEARANCE_FORM_KEYS={
 1:['handednessChoice','handD100'],
 14:['complexionChoice','complexionD100','hairChoice','hairD100','eyesChoice','eyesD100'],
 10:['heightChoice','buildD100','weightExtraChoice','weightDice']
};
function persistAppearanceStep(original,updated,step,form){
 const keys=APPEARANCE_FORM_KEYS[step];if(!keys)return;
 const oldPrefs=original.hmk?.creation?.values?.appearancePreferences||{};
 const next={...oldPrefs};
 for(const key of keys)next[key]=String(form.elements.namedItem(key)?.value||'').trim();
 const oldH=original.hmk||{},newH=updated.hmk||{};
 const folkChanged=String(oldH.folk||'')!==String(newH.folk||'');
 const regionChanged=String(oldH.birthRegion||'')!==String(newH.birthRegion||'');
 const oldStr=oldH.creation?.attributeProof?.str?.adultMinimum;
 const newStr=newH.creation?.attributeProof?.str?.adultMinimum;
 const strChanged=oldStr!==newStr;
 // Prerequisites: Folk controls every table; birthplace controls complexion,
 // hair and eyes; STR controls height and weight. Clear only affected inputs.
 if(folkChanged){for(const key of Object.keys(next))if(!['handednessChoice','handD100'].includes(key))delete next[key];}
 else{
  if(regionChanged)for(const key of APPEARANCE_FORM_KEYS[5])delete next[key];
  if(strChanged)for(const key of APPEARANCE_FORM_KEYS[10])delete next[key];
 }
 // The currently submitted choices override invalidation only if they are
 // deliberate NEW choices from this very step, not an old archived field.
 if((step===14&&regionChanged)||(step===10&&strChanged)){
  for(const key of keys)next[key]=String(form.elements.namedItem(key)?.value||'').trim();
 }
 const oldProof=original.hmk?.appearanceProof;
 const touched=new Set(keys.filter(key=>String(next[key]||'')!==String(oldPrefs[key]||'')));
 if(oldProof&&!folkChanged&&!regionChanged&&!strChanged&&touched.size===0){
  // No Appearance edit: do not rewrite an existing original random proof,
  // its provenance or any historical dice when browsing earlier steps.
  updated.hmk.creation.values.appearancePreferences=next;
  return;
 }
 const complexionDifferent=Boolean(oldProof&&(
  (next.complexionChoice&&next.complexionChoice!==oldProof.values?.complexion)||
  (next.complexionD100&&Number(next.complexionD100)!==oldProof.rolls?.complexionD100)));
 // Preserve original dice for unaffected details when returning to a
 // completed profile: no re-roll and no conversion of a die into a choice.
 if(oldProof){
  const preserve=(field,choiceKey,rollKey,invalid)=>{
   if(invalid||touched.has(choiceKey)||touched.has(rollKey)||next[choiceKey]||next[rollKey])return;
   if(oldProof.rolls?.[rollKey]!==undefined)next[rollKey]=String(oldProof.rolls[rollKey]);
   else if(oldProof.methods?.[field]==='choice'&&oldProof.values?.[field])next[choiceKey]=String(oldProof.values[field]);
  };
  preserve('handedness','handednessChoice','handD100',folkChanged);
  for(const [field,choice,roll]of [['complexion','complexionChoice','complexionD100'],['hair','hairChoice','hairD100'],['eyes','eyesChoice','eyesD100']])preserve(field,choice,roll,folkChanged||regionChanged||(field!=='complexion'&&complexionDifferent));
  preserve('height','heightChoice','buildD100',folkChanged||strChanged);
  if(!folkChanged&&!strChanged&&!touched.has('weightExtraChoice')&&!touched.has('weightDice')&&!next.weightExtraChoice&&!next.weightDice){
   if(oldProof.rolls?.weightD6?.length===3)next.weightDice=oldProof.rolls.weightD6.join(',');
   else if(oldProof.build?.weightDice?.length===3)next.weightDice=oldProof.build.weightDice.join(',');
   else if(oldProof.methods?.weight==='choice'&&Number.isInteger(oldProof.build?.weightExtra))next.weightExtraChoice=String(oldProof.build.weightExtra);
  }
 }
 // Truncate invalid values in source-dependent lists, rather than silently
 // keeping complexion/hair/eye results from another Folk or home region.
 const prev=appearanceOptions({folk:newH.folk,region:newH.birthRegion||newH.creation?.values?.birthRegion});
 for(const [choice,allowed]of [['handednessChoice',prev.handedness],['complexionChoice',prev.complexion]]){
  if(next[choice]&&!allowed.includes(next[choice]))delete next[choice];
 }
 // At this point `generateAppearance(...,manual)` rejects contradictory
 // choice+die and validates each dependent result. A manual character may
 // deliberately leave everything unanswered: Appearance is optional.
 updated.hmk.creation.values.appearancePreferences=next;
 const proof=generateAppearance(updated,()=>{throw Error('Ruční tvorba nesmí vyvolat automatický hod Appearance');},next,'manual');
 if(oldProof){
  // Preserve the distinction between genuine historical software rolls and
  // manually entered dice when the user edits some OTHER optional field.
  for(const key of Object.keys(proof.values)){
   if(proof.values[key]===oldProof.values?.[key]&&
     !touched.has(key+'Choice')&&
     !touched.has(({handedness:'handD100',complexion:'complexionD100',hair:'hairD100',eyes:'eyesD100',height:'buildD100',weight:'weightDice'})[key]))
    proof.methods[key]=oldProof.methods?.[key]||proof.methods[key];
  }
 }
 for(const key of ['handedness','complexion','hair','eyes','height','weight']){
  if(Object.hasOwn(proof.values,key))updated.hmk[key]=proof.values[key];
  else if(folkChanged||touched.has(key+'Choice')||
     (key==='handedness'&&touched.has('handD100'))||
     (key==='complexion'&&touched.has('complexionD100'))||
     (key==='hair'&&touched.has('hairD100'))||
     (key==='eyes'&&touched.has('eyesD100'))||
     (['hair','eyes'].includes(key)&&complexionDifferent)||
     (regionChanged&&['complexion','hair','eyes'].includes(key))||
     (strChanged&&['height','weight'].includes(key)))delete updated.hmk[key];
 }
 if(Object.keys(proof.values).length)updated.hmk.appearanceProof=proof;
 else if(folkChanged||regionChanged||strChanged)delete updated.hmk.appearanceProof;
}
/** Recalculate dependent dropdowns without losing other character inputs. */
function refreshAppearanceSelects(form,original){
 const step=creationOf(original).step;if(step!==1&&step!==14)return;
 const folk=String(form.elements.namedItem('folk')?.value||original.hmk?.folk||'Human');
 const region=String(form.elements.namedItem('birthRegion')?.value||original.hmk?.birthRegion||'');
 let complexion=String(form.elements.namedItem('complexionChoice')?.value||'');
 const complexionDie=String(form.elements.namedItem('complexionD100')?.value||'').trim();
 if(!complexion&&complexionDie){
  try{
   const mock={...original,hmk:{...original.hmk,folk,birthRegion:region,creation:{...original.hmk.creation,values:{...original.hmk.creation.values,appearancePreferences:{complexionD100:complexionDie}}}}};
   complexion=generateAppearance(mock,()=>{throw Error('Není dovoleno přehazovat')},{complexionD100:complexionDie},'manual').values.complexion||'';
  }catch{}
 }
 const opts=appearanceOptions({folk,region,complexion});
 for(const [name,values]of [['handednessChoice',opts.handedness],['complexionChoice',opts.complexion],['hairChoice',opts.hair],['eyesChoice',opts.eyes]]){
  const select=form.elements.namedItem(name);if(!select||select.tagName!=='SELECT')continue;
  const before=select.value;
  const lead=select.options[0]?.textContent||'Náhodně / volitelně';
  select.replaceChildren(new Option(lead,''),...values.map(x=>new Option(x,x)));
  select.value=values.includes(before)?before:'';
 }
}
document.addEventListener('change',event=>{
 const form=event.target?.closest?.('#creation-step-form');if(!form)return;
 if(['folk','complexionChoice','complexionD100'].includes(event.target?.name))refreshAppearanceSelects(form,character(selected));
},false);
// Optional Appearance does not invalidate a completed character or reopen
// the mandatory 14-step validation. This separate save also preserves the
// full history of software-generated dice for all unaffected attributes.
document.addEventListener('click',event=>{
 const control=event.target.closest?.('[data-appearance-save]');if(!control)return;
 event.preventDefault();event.stopImmediatePropagation();
 if(combatInitiativeSequence||storageReadOnly){alert('Nyní nelze ukládat Appearance.');return;}
 const form=control.closest('#creation-step-form'),original=character(selected);
 if(!form||!original)return;
 const step=creationOf(original).step;
 if(step===1&&form.elements.namedItem('folk')?.value&&form.elements.namedItem('folk').value!==original.hmk.folk){alert('Nejprve potvrďte změnu Folk tlačítkem Uložit a pokračovat.');return;}
 
 try{
  const updated=structuredClone(original);
  persistAppearanceStep(original,updated,step,form);
  const ok=mutate(()=>Object.assign(character(selected),updated));
  if(ok){notice='Volitelný Appearance uložen. Čtrnáct kroků pravidlové tvorby zůstalo beze změny.';render();}
 }catch(err){alert('Appearance: '+err.message);}
},true);

// Clear, deterministic validation guidance for the *current* manual step.
// Keep the unsaved fields in place; never mutate the character on failure.
function creationPsycheProblemField(form,message){
 if(!/psyche/i.test(message||''))return null;
 const get=name=>[...form.querySelectorAll('input,select,textarea')].find(x=>x.name===name);
 const dice=get('psycheDice');if(!dice)return null;
 const actor=selected?character(selected):null;
 const count=actor?creationPsycheCount(actor.hmk?.folk,actor.hmk?.ageGroup):null;
 if(count===null)return dice;
 const parts=String(dice.value||'').split(',').map(x=>x.trim()).filter(Boolean);
 if(parts.length!==count||parts.some(x=>!/^(?:[1-9]|1\d|20)$/.test(x)))return dice;
 const rolls=parts.map(Number);
 const sum=rolls.reduce((total,n)=>total+(n===20?3:n===19?2:n===18?1:0),0);
 const wanted=psycheIntensity(sum).length;
 for(let i=1;i<=2;i++){
  const choice=get('psycheTraitChoice'+i),traitDie=get('psycheTraitDie'+i);
  const selectedValue=choice?.value||'',dieValue=traitDie?.value?.trim()||'';
  if(i<=wanted){
   if(dieValue&&!/^(?:[1-9]|10)$/.test(dieValue))return traitDie;
   if(dieValue&&selectedValue&&selectedValue!==CREATION_PSYCHE_TRAITS[Number(dieValue)-1])return choice;
   if(!dieValue&&!selectedValue)return choice;
  }else if(dieValue||selectedValue)return dieValue?traitDie:choice;
 }
 return dice;
}
function creationProblemField(form,message){
 const text=String(message||'');
 const psyche=creationPsycheProblemField(form,text);if(psyche)return psyche;
 const choices=[
  [/divine\s+aspects?|grace\s*nebo\s*marked|grace\s*aspect|vyberte jeden z 12/i,['graceAspect']],
  [/grace.*d20|fyzick.*grace/i,['graceDie']],
  [/psyche.*trait/i,['psycheTraitChoice1','psycheTraitDie1','psycheDice']],
  [/psyche/i,['psycheDice']],
  [/doctrine/i,['doctrineSubject0','ritualSkill']],
  [/ritual/i,['ritualSkill','nativeRitualChoice']],
  [/folk/i,['folk','folkRoll']],
  [/age|v[eě]kov/i,['ageGroup','ageRoll']],
  [/sunsign.*trait/i,['sunsignTraits','traitRoll']],
  [/sunsign|birthday|birthdate/i,['birthMonth','birthDay']],
  [/birthplace|realm|region/i,['birthRegion','birthplace']],
  [/class/i,['socialClass','classRoll']],
  [/occupation/i,['occupation','familyOccupation']],
  [/background/i,['background','backgroundRoll']],
  [/estrangement/i,['estrangementRoll']],
  [/wealth/i,['wealthMethod','wealthDice']],
  [/attributes|attribute|strength|voice|aura/i,['creation-attr-name','die0']],
  [/skill|DP/i,['skillName','skillDP']],
 ];
 const byName=name=>[...form.querySelectorAll('input,select,textarea')].find(el=>el.name===name||el.id===name);
 for(const [regex,fields]of choices)if(regex.test(text))for(const field of fields){const el=byName(field);if(el)return el;}
 // Prefer a genuinely empty editable field over arbitrarily marking a valid one.
 return [...form.querySelectorAll('select,input,textarea')].find(el=>el.required&&!el.disabled&&!String(el.value||'').trim())||null;
}
function updateCreationPsycheGuidance(form){
 const output=form.querySelector('[data-psyche-guidance]');if(!output)return;
 const dice=form.elements.namedItem('psycheDice');if(!dice)return;
 const actor=selected?character(selected):null;
 const count=actor?creationPsycheCount(actor.hmk?.folk,actor.hmk?.ageGroup):null;
 if(count===null)return;
 const parts=String(dice.value||'').split(',').map(x=>x.trim()).filter(Boolean);
 if(parts.length!==count||parts.some(x=>!/^(?:[1-9]|1\d|20)$/.test(x))){
  output.textContent=`Nejdřív vyplňte ${count}× Psyche d20; bez nich nelze určit, zda Trait vzniká. Samotný výběr názvu nestačí.`;
  return;
 }
 const sum=parts.map(Number).reduce((total,n)=>total+(n===20?3:n===19?2:n===18?1:0),0);
 const intensities=psycheIntensity(sum);
 output.textContent=`Psyche d20 potvrzují součet ${sum}: ${intensities.length?intensities.join(' + '):'žádný počáteční Trait'}. ${intensities.length?'Nyní vyberte odpovídající názvy nebo zadejte Trait d10.':'Obě pole Psyche Trait musejí zůstat prázdná.'}`;
}
function showCreationProblem(form,message,preferred=null){
 const actor=selected?character(selected):null;
 if(actor)updateCreationStepUI(creationOf(actor).step,'invalid',String(message||''));
 form.querySelectorAll('.hmk-creation-invalid').forEach(el=>{el.classList.remove('hmk-creation-invalid');el.removeAttribute('aria-invalid')});
 form.querySelectorAll('.hmk-creation-invalid-label').forEach(el=>el.classList.remove('hmk-creation-invalid-label'));
 const output=form.querySelector('.hmk-creation-validation')||document.createElement('p');
 output.className='hmk-creation-validation';output.setAttribute('role','alert');output.textContent='Je třeba doplnit nebo opravit: '+String(message);
 if(!output.isConnected)form.querySelector('.creation-inputs')?.prepend(output);
 const control=preferred||creationProblemField(form,message);
 if(control){
  control.classList.add('hmk-creation-invalid');control.setAttribute('aria-invalid','true');
  const label=control.closest('label,fieldset');label?.classList.add('hmk-creation-invalid-label');
  (label||control).scrollIntoView({block:'center',behavior:'smooth'});
  try{control.focus({preventScroll:true})}catch{}
 }else output.scrollIntoView({block:'center',behavior:'smooth'});
}
function clearCreationProblem(event){
 const form=event.target?.closest?.('#creation-step-form');if(!form)return;
 const el=event.target;
 if(el?.classList?.contains('hmk-creation-invalid')){
  el.classList.remove('hmk-creation-invalid');el.removeAttribute('aria-invalid');
  el.closest('label,fieldset')?.classList.remove('hmk-creation-invalid-label');
 }
 if(!form.querySelector('.hmk-creation-invalid'))form.querySelector('.hmk-creation-validation')?.remove();
}
function markCreationFormEditing(event){
 const form=event.target?.closest?.('#creation-step-form');
 if(!form||automaticGenerationBusy)return;
 const control=event.target;
 if(!control.matches?.('input,select,textarea')||control.type==='hidden')return;
 const actor=selected?character(selected):null;if(!actor)return;
 const step=creationOf(actor).step;
 if(creationUIStatus(actor.id,step)?.kind==='invalid')return; // remains red until saved
 updateCreationStepUI(step,'editing');
}
document.addEventListener('input',markCreationFormEditing,true);
document.addEventListener('change',markCreationFormEditing,true);
document.addEventListener('input',clearCreationProblem,true);
document.addEventListener('change',clearCreationProblem,true);
document.addEventListener('input',event=>{const f=event.target?.closest?.('#creation-step-form');if(f)updateCreationPsycheGuidance(f);},true);
document.addEventListener('change',event=>{const f=event.target?.closest?.('#creation-step-form');if(f)updateCreationPsycheGuidance(f);},true);
document.addEventListener('invalid',event=>{
 const form=event.target?.closest?.('#creation-step-form');if(!form||automaticGenerationBusy)return;
 const actor=selected?character(selected):null;
 if(actor)updateCreationStepUI(creationOf(actor).step,'invalid','Nevyplněné nebo nesprávné pole');
 event.target.classList.add('hmk-creation-invalid');event.target.setAttribute('aria-invalid','true');
 event.target.closest('label,fieldset')?.classList.add('hmk-creation-invalid-label');
 // Native validation focuses and scrolls to the first missing field.
},true);

// HMK v1.2 Character Creation. Capture the new forms before legacy editors;
// all persistent changes flow through the existing mutate()/CAS save().
document.addEventListener('submit',event=>{
 const form=event.target;
 if(!['creation-new-form','creation-step-form'].includes(form?.id))return;
 event.preventDefault();event.stopImmediatePropagation();
 if(combatInitiativeSequence)return alert('Character Creation / Edit není povolen během aktivní Initiative.');
 if(storageReadOnly)return alert('Úložiště je pouze pro čtení.');
 const v=Object.fromEntries(new FormData(form));
 if(form.id==='creation-new-form'){
  const name=String(v.name||'').trim();if(!name)return alert('Zadejte jméno postavy.');
  const id=uuid();const success=mutate(()=>data.characters.push({id,name,kind:v.kind==='NPC'?'NPC':'PC',occupation:'',description:'',portrait:'',hmk:{creation:defaultCreation(),skills:[],injuries:[],attributes:{}}}));
  if(success){selected=id;view='creation';overlay=null;render();}return;
 }
 const original=character(selected);if(!original)return;
 const c=creationOf(original),step=c.step,action=event.submitter?.value||'next';
 let patch={step,values:{},advance:action==='next'};
 for(const [k,val] of Object.entries(v))if(['folk','ageGroup','birthMonth','birthDay','sunsignTraits','sunsignTraitSecondary','traitRollSecondary','birthplace','society','socialClass','familyOccupation','familyWeaponcrafterType','familyMartialChoice','familyVariantChoice','familyRitualChoice','familyScriptChoice','familySecondScriptChoice','familyThirdScriptChoice','background','estrangementRoll','occupation','wealth','folkRoll','ageRoll','traitRoll','classRoll','classDie','backgroundRoll','backgroundTensRoll','urbanChance','tribalUnsettled','birthRegion','regionRoll','venariveRoll','nativeLanguageRoll','regionSubRoll','regionDialectRoll','nativeLanguageChoice','regionTribeRoll','regionCommunityChoice','regionDialectChoice','regionAzeriDialectChoice','subsistence','parentOccupationRoll','parentOccupationSubRoll','parentOccupationSpecialRoll','parentOccupationConvocationRoll','familyAuto','backgroundAuto','viking','occupationAuto','occupationScriptChoice','occupationLanguageChoice','occupationLanguageDistribution','occupationScriptsDistribution','occupationSecondScriptChoice','occupationThirdScriptChoice','backgroundCityLanguageDistribution','occupationRitualChoice','nativeSkillsMode','nativeRitualChoice','nativeRitualChoice2','nativeRitualChoice3','wealthMethod','parentWealthDie','occupationWealthDie','familyDice','occupationDice','wealthAdvantage','ritualML','ritualClergy','ritualFightingOrder','orthodoxyPenalty','folkAuto','folkDice','arcaneTalentMode','veteranRoundsMode','veteranRound','graceDie','pvarismML','psycheDice','psycheTraitChoice1','psycheTraitChoice2','psycheTraitDie1','psycheTraitDie2','ritualSkill','graceAspect','moralityChoice'].includes(k))patch.values[k]=val;
 // A typed physical die is authoritative; HTML selects may be blank or
 // contain an older choice while the GM is editing the roll.
 try{patch.values=mergeCreationChoices(original,step,patch.values,c.values,{strict:false})}
 catch(err){if(automaticGenerationDebug)console.warn('Auto creation validation:',err.message,'step',step,'action',action);if(!automaticGenerationBusy){alert('HMK Character Creation: '+err.message);showCreationProblem(form,err.message)}return}
 if(step===14&&action==='next'&&!automaticGenerationBusy){
  const graceRoll=String(v.graceDie||c.values?.graceProof?.roll||'').trim();
  const graceAspect=String(v.graceAspect||'').trim();
  if(graceRoll&&Number(graceRoll)>=15&&Number(graceRoll)<=20&&!graceAspect){
   const message='Divine Grace d20 '+graceRoll+' vyžaduje jeden z 12 Divine Aspects (HMK str. 53 a 310).';
   alert('HMK Character Creation: '+message);
   showCreationProblem(form,message,form.elements.namedItem('graceAspect'));
   return;
  }
 }
 if(action==='attribute'){
  const next=ATTRIBUTES.find(name=>!c.attributeProof?.[name]);
  const attributeName=next||creationAttributeChoice||ATTRIBUTES[0];
  const req=physicalDiceRequirement(original.hmk?.ageGroup,original.kind,ATTRIBUTES.indexOf(attributeName)>=6);
  patch={...patch,advance:false,attribute:{name:attributeName,dice:Array.from({length:req.count},(_,i)=>v['die'+i])}};
 } else if(action==='voice'){
  const req=voiceDiceRequirement(original.hmk?.folk);
  patch={...patch,advance:false,voice:{dice:Array.from({length:req.count},(_,i)=>v['die'+i])}};
 } else if(action==='folk'){
  patch={...patch,advance:false,folkSkillDice:String(v.folkDice||'').split(',').map(x=>x.trim()).filter(Boolean)};
 } else if(action==='talent-prereq'){
  patch={...patch,advance:false,arcaneTalentDice:{d20:v.arcaneTalentD20,d20s:v.arcaneTalentD20s?String(v.arcaneTalentD20s).split(',').map(x=>x.trim()).filter(Boolean):undefined,d100s:String(v.arcaneTalentD100s||'').split(',').map(x=>x.trim()).filter(Boolean)}};
 } else if(action==='talent'){
  patch={...patch,advance:false,arcaneTalentDice:{d20:v.arcaneTalentD20,d20s:v.arcaneTalentD20s?String(v.arcaneTalentD20s).split(',').map(x=>x.trim()).filter(Boolean):undefined,d100s:String(v.arcaneTalentD100s||'').split(',').map(x=>x.trim()).filter(Boolean)}};
 } else if(action==='gmbonus'){
  patch={...patch,advance:false,gmBonusLanguageUpdate:{decision:String(v.gmBonusDecision||''),distribution:String(v.gmBonusDistribution||'')}};
 } else if(action==='skill'){
  patch={...patch,advance:false,skillAllocation:{skillName:v.skillName,dp:Number(v.skillDP),veteranRound:v.veteranRound?Number(v.veteranRound):undefined}};
 }
 if(step===10&&action==='next'&&String(v.moralityDice||'').trim()){
  patch.moralityDice=String(v.moralityDice).split(',').map(x=>x.trim());
 }
 if(step===13&&action==='next'&&v.wealthMethod==='dice'){
  patch.wealthDice={parentDie:Number(v.parentWealthDie),occupationDie:Number(v.occupationWealthDie),
   familyRolls:String(v.familyDice||'').split(',').map(x=>x.trim()).filter(Boolean),
   occupationRolls:String(v.occupationDice||'').split(',').map(x=>x.trim()).filter(Boolean),
   advantage:v.wealthAdvantage!=='no'};
 }
 // Religion status must be applied with the selected Ritual Skill, not gated
 // by the non-existent manual ritualML input. The skill ML is authoritative.
 if(step===14&&action==='next'){
  patch.mysteries??={};
  if(v.graceDie!==undefined&&v.graceDie!=='')patch.mysteries.graceDie=Number(v.graceDie);
  patch.mysteries.graceAspect=v.graceAspect||'';
  if(v.pvarismML!==undefined&&v.pvarismML!=='')patch.mysteries.pvarismML=Number(v.pvarismML);
  if(v.ritualSkill)patch.mysteries.ritualSkill=v.ritualSkill;
  if(v.ritualSkill){
   patch.mysteries.clergy=v.ritualClergy==='yes';
   patch.mysteries.fightingOrder=v.ritualFightingOrder==='yes';
   if(v.moralityChoice!==undefined&&v.moralityChoice!=='')patch.mysteries.morality=Number(v.moralityChoice);
   patch.mysteries.doctrineSubjects=Array.from({length:5},(_,i)=>v['doctrineSubject'+i]).filter(Boolean);
  }
  const aRows=Array.from({length:10},(_,i)=>v['startingElixir'+i]).filter(Boolean);
  if(aRows.length||form.querySelector('[name="startingElixir0"]'))patch.mysteries.elixirs=aRows;
  if(String(original.occupation??'').startsWith('Shèk-Pvâr (')){
   const selections=new FormData(form);
   patch.mysteries.pvarPrimary=String(original.occupation).slice('Shèk-Pvâr ('.length,-1);
   patch.mysteries.chantryStars=Number(v.pvarChantryStars);
   if(v.pvarChantryId)patch.mysteries.pvarChantryId=v.pvarChantryId;
   patch.mysteries.pvarSpells=[...selections.getAll('pvarAssistedSpells').map(id=>({id,assisted:true})),...selections.getAll('pvarUnassistedSpells').map(id=>({id,assisted:false}))];
   patch.mysteries.pvarArtefacts=Array.from({length:4},(_,i)=>{
    if(!v['pvarArtifactKind'+i])return null;
    return {kind:v['pvarArtifactKind'+i],enchantments:[v['pvarArtifactSpell'+i],v['pvarArtifactSpellExtra'+i]].filter(Boolean),result:v['pvarArtifactResult'+i],duration:v['pvarArtifactDuration'+i]};
   }).filter(Boolean);
   if(v.pvarGuildRank)patch.mysteries.pvarGuildRank=v.pvarGuildRank;
   if(v.pvarAttunedObject)patch.mysteries.pvarAttunedObject=v.pvarAttunedObject;
   if(v.pvarChantryName)patch.mysteries.pvarChantryName=v.pvarChantryName;
   patch.mysteries.pvarChantryConvocation=v.pvarChantryConvocation;
  }
  if(String(original.occupation??'').startsWith('Shaman (')){
   patch.mysteries.shamanTradition=v.shamanTradition||'';
   patch.mysteries.shamanKathTotem=v.shamanKathTotem||'';
  }
  if(String(original.occupation??'').startsWith('Shaman (')){
   const powers=[];for(let i=0;i<20;i++){
    const token=String(v['spiritPower'+i]??'');if(!token)continue;
    const parts=token.split('::');if(parts.length!==3)return alert('Neplatná volba Spirit Power.');
    powers.push({family:parts[0],subject:parts[1],anima:Number(parts[2]),talisman:v['spiritTalisman'+i]==='yes'});
   }
   patch.mysteries.spiritPowers=powers;
  }
  if(v.psycheDice!==undefined){
   // An empty field is an explicit incomplete edit: never silently reuse an
   // old completed Psyche proof while the currently visible dice are blank.
   if(!String(v.psycheDice).trim()){
    if(!automaticGenerationBusy)showCreationProblem(form,'HMK p.40: chybí povinné Psyche d20. Nejdřív zadejte výsledky d20; samotný výběr Traitu neurčuje, zda Trait vznikl.');
    return;
   }
   const rolls=String(v.psycheDice).split(',').map(x=>x.trim());
   const dice=[v.psycheTraitDie1,v.psycheTraitDie2].map(x=>x===''?null:x);
   const choices=[v.psycheTraitChoice1,v.psycheTraitChoice2];
   patch.mysteries.psyche={d20s:rolls,d10s:dice,choices};
  }
 }
 if(step===14&&action==='next'){
  const pending=creationRevisionIssues(original).filter(i=>i.step<14);
  if(pending.length){render();document.querySelector('.folio-creation-revision')?.scrollIntoView({block:'start',behavior:'smooth'});return;}
 }
 let updated;try{updated=applyCreationPatch(original,patch);persistAppearanceStep(original,updated,step,form);syncCreationSkills(updated.hmk,uuid)}catch(err){if(automaticGenerationDebug)console.warn('Auto creation validation:',err.message,'step',step,'action',action);if(!automaticGenerationBusy){alert('HMK Character Creation: '+err.message);showCreationProblem(form,err.message)}return}
 const beforeUI=creationUIStatus(original.id,step);
 clearCreationStepUI(original.id,step);
 const success=mutate(()=>{const entry=character(selected);if(!entry)throw Error('Postava neexistuje');Object.assign(entry,updated)});
 if(!success&&beforeUI)creationStepUIState.set(creationStepUIKey(original.id,step),beforeUI);
 if(success&&updated.hmk?.creation?.status==='review-required'&&action==='next'){
  if(characterJournalReadiness(character(selected)).ready){view='sheet';notice='';render();}
  else{view='creation';render();}
 }
},true);

document.addEventListener('click',event=>{
 const focus=event.target.closest?.('[data-creation-review-focus]');
 if(focus){event.preventDefault();const name=focus.dataset.creationReviewFocus;
  const field=[...document.querySelectorAll('#creation-step-form input,#creation-step-form select,#creation-step-form textarea')].find(el=>el.name===name||el.id===name);
  const element=field||document.querySelector('#creation-step-form .folio-creation-revision-target');
  element?.scrollIntoView({block:'center',behavior:'smooth'});field?.focus({preventScroll:true});return;
 }
 const t=event.target.closest?.('[data-creation-back],[data-creation-leave],[data-creation-jump],[data-creation-step],[data-creation-select-attr],[data-creation-edit-voice]');if(!t)return;
 event.preventDefault();event.stopImmediatePropagation();
 if(t.hasAttribute('data-creation-leave')){
  if(characterJournalReadiness(character(selected)).ready){view='sheet';notice='';}
  else{view='characters';notice='Deník postavy bude dostupný až po dokončení všech 14 kroků a závěrečné revizi.';}
  render();return
 }
 if(t.hasAttribute('data-creation-edit-voice')){creationAttributeChoice='voi';render();return}
 if(t.hasAttribute('data-creation-select-attr')){creationAttributeChoice=document.getElementById('creation-attr-name')?.value||null;render();return}
 if(combatInitiativeSequence)return alert('Během aktivní Initiative nelze měnit Character Creation.');
 const original=character(selected);if(!original)return;
 const c=creationOf(original);
 const direct=t.hasAttribute('data-creation-step')?Number(t.dataset.creationStep):null;
 if(direct!==null&&(!Number.isInteger(direct)||direct<1||direct>creationReachableStep(original,c)))return;
 if(direct===c.step)return;
 const target=direct??(t.hasAttribute('data-creation-jump')?Number(document.getElementById('creation-jump-select')?.value):null);
 let patched;try{patched=applyCreationPatch(original,{step:c.step,jump:target,back:t.hasAttribute('data-creation-back')});syncCreationSkills(patched.hmk,uuid)}catch(err){return alert(err.message)}
 mutate(()=>Object.assign(character(selected),patched));
},true);

// Transparent, non-AI live preview. The preview is advisory only; no
// creation state is mutated until the ordinary validated generator runs.
function updateGeneratorSemanticPreview(form){
 const target=form?.querySelector('#generator-semantic-preview');if(!target)return;
 const v=new FormData(form),parsed=interpretCharacterDescription(String(v.get('description')||''),v.getAll('trait').map(String));
 const label={warrior:'bojovník',scholar:'učenec',mystic:'mystik',artisan:'řemeslník',explorer:'cestovatel',social:'společenský',covenant:'Covenant',random:'nerozpoznáno'};
 const certainty={unknown:'bez dostatečných indicií',low:'nízká',medium:'střední',high:'vyšší'};
 const occupation=parsed.occupationCandidates.slice(0,3).join(', ')||'neurčeno';
 const skills=parsed.skillPreferences.slice(0,7).join(', ')||'neurčeny';const physical=Object.entries(parsed.attributeAspirations).map(([key,v])=>key+': '+(v.higher.length?'vyšší':'')+(v.lower.length?'nižší':'')).join(', ')||'neuvedeny';
 const contradictory=parsed.contradictions.length?`<p>Rozpor / negace: ${esc(parsed.contradictions.join(', '))}</p>`:'';
 const matches=parsed.evidence.filter(e=>e.source==='text').slice(0,9).map(e=>(e.negated?'[zápor] ':'')+e.expression+' → '+e.key).join('; ');
 target.innerHTML=`<strong>Lokální výklad:</strong> ${esc(label[parsed.primary])} · jistota ${esc(certainty[parsed.confidence])}.<p>Rozpoznaná profese: ${esc(occupation)}. Preferované dovednosti: ${esc(skills)}.</p><p>Folk: ${esc(parsed.folkPreference||'neurčen')} · věk: ${esc(parsed.agePreference||'neurčen')} · popisné rysy: ${parsed.narrativeTraits.length} · sémantické indicie: ${parsed.evidence.length}.</p><p>Požadované vlastnosti (nepřepisují kostky): ${esc(physical)}.</p><p><strong>Rozpoznané výrazy:</strong> ${esc(matches||'zatím žádné')}.</p>${contradictory}${parsed.uncertainties?.length?`<p><strong>Nejistoty:</strong> ${esc(parsed.uncertainties.slice(0,4).join('; '))}</p>`:''}<p>Jen místní pravidla a slovníky, bez AI a sítě. Výklad může být chybný; platnost povolání a dovedností ověřuje HMK průvodce.</p>`;
}
document.addEventListener('input',e=>{const f=e.target?.closest?.('#hmk-generator-config');if(f)updateGeneratorSemanticPreview(f);},true);
document.addEventListener('change',e=>{const f=e.target?.closest?.('#hmk-generator-config');if(f)updateGeneratorSemanticPreview(f);},true);
// Contextual generator panel: native form submission is prevented and its
// choices flow through the existing 14-stage validator, not a second engine.
document.addEventListener('submit',e=>{
 if(e.target?.getAttribute('id')!=='hmk-random-name-form')return;
 e.preventDefault();e.stopImmediatePropagation();
 if(!e.target.reportValidity())return;
 const values=new FormData(e.target);const name=String(values.get('name')||'').trim();
 if(!name){alert('Nejdříve zadejte jméno postavy.');return;}
 overlay=null;
 void generateCharacterFullyAutomatically('random','random',{name,kind:values.get('kind')==='NPC'?'NPC':'PC'});
},true);
document.addEventListener('submit',e=>{
 if(e.target?.getAttribute('id')!=='hmk-generator-config')return;
 e.preventDefault();e.stopImmediatePropagation();
 const v=new FormData(e.target);
 const traits=v.getAll('trait').map(String);
 const preferences={name:String(v.get('name')||'').trim(),kind:v.get('kind')==='NPC'?'NPC':'PC',folk:String(v.get('folk')||''),occupation:String(v.get('occupation')||''),traits,description:String(v.get('description')||'')};
 const profile=String(v.get('profile')||'random');
 void generateCharacterFullyAutomatically('traits',profile,preferences);
},true);


/* Fixed glossary tooltip: no pseudo-element clipping inside tables or book rails. */
let hmkJournalTooltip=null,hmkJournalTooltipTarget=null;
function hmkHideJournalTooltip(){if(hmkJournalTooltip)hmkJournalTooltip.hidden=true;hmkJournalTooltipTarget=null;}
function hmkShowJournalTooltip(element){
 if(!element||!element.isConnected||!element.closest('.journal-book, .hc-trek-routine'))return;
 const explanation=element.getAttribute('data-hmk-help');if(!explanation)return;
 // The custom help bubble is authoritative; the native browser title
 // would display a second (white) bubble with the same explanation.
 if(element.hasAttribute('title'))element.removeAttribute('title');
 if(!hmkJournalTooltip){
  hmkJournalTooltip=document.createElement('div');
  hmkJournalTooltip.className='hmk-journal-floating-tooltip';
  hmkJournalTooltip.setAttribute('role','tooltip');
  hmkJournalTooltip.hidden=true;
  document.body.appendChild(hmkJournalTooltip);
 }
 hmkJournalTooltipTarget=element;
 hmkJournalTooltip.classList.toggle('hmk-trek-dice-outcomes',!!element.closest('.hc-trek-die-row'));
 hmkJournalTooltip.textContent=explanation;
 hmkJournalTooltip.hidden=false;
 hmkJournalTooltip.style.left='0px';hmkJournalTooltip.style.top='0px';
 const target=element.getBoundingClientRect();const tooltip=hmkJournalTooltip.getBoundingClientRect();
 const vw=document.documentElement.clientWidth,vh=document.documentElement.clientHeight;
 let x=Math.max(8,Math.min(vw-tooltip.width-8,target.left));
 let y=target.top-tooltip.height-9;
 if(y<8)y=target.bottom+9;
 if(y+tooltip.height>vh-8)y=Math.max(8,vh-tooltip.height-8);
 hmkJournalTooltip.style.left=Math.round(x)+'px';
 hmkJournalTooltip.style.top=Math.round(y)+'px';
}
// Highlight contextual ? only while the pointer actually targets that button.
// CSS :hover alone can linger on nested labels after layout/scroll changes.
document.addEventListener('pointerover',event=>{
 const button=event.target?.closest?.('button.hmk-rule-help');
 if(button)button.classList.add('hmk-help-direct-hover');
},true);
document.addEventListener('pointerout',event=>{
 const button=event.target?.closest?.('button.hmk-rule-help');
 if(button&&!button.contains(event.relatedTarget))button.classList.remove('hmk-help-direct-hover');
},true);
document.addEventListener('pointerover',event=>{
 const target=event.target?.closest?.('[data-hmk-help]');
 if(target?.hasAttribute('title'))target.removeAttribute('title');
 if(target&&target!==hmkJournalTooltipTarget)hmkShowJournalTooltip(target);
},true);
document.addEventListener('pointerout',event=>{
 if(!hmkJournalTooltipTarget)return;
 const next=event.relatedTarget;
 if(next&&hmkJournalTooltipTarget.contains(next))return;
 if(event.target===hmkJournalTooltipTarget||hmkJournalTooltipTarget.contains(event.target))hmkHideJournalTooltip();
},true);
document.addEventListener('focusin',event=>{
 const target=event.target?.closest?.('[data-hmk-help]');
 if(target?.hasAttribute('title'))target.removeAttribute('title');
 if(target)hmkShowJournalTooltip(target);
},true);
document.addEventListener('focusout',event=>{
 if(hmkJournalTooltipTarget&&event.target===hmkJournalTooltipTarget)hmkHideJournalTooltip();
},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape')hmkHideJournalTooltip();},true);
document.addEventListener('scroll',()=>{if(hmkJournalTooltipTarget)hmkHideJournalTooltip();},true);

// Private GitHub cloud controls. This UI never asks users to upload/download JSON.
document.addEventListener('submit',async e=>{
 if(e.target?.id!=='hmk-cloud-connect-form')return;
 e.preventDefault();const form=e.target;
 const owner=String(new FormData(form).get('owner')||'').trim();
 const repo=String(new FormData(form).get('repo')||'').trim();
 const token=String(new FormData(form).get('token')||'').trim();
 const rememberDevice=!!form.querySelector('[name=rememberDevice]')?.checked;
 const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;
 try{const result=await cloudSync.connect({owner,repo,accessToken:token,rememberDevice});
  if(result.needsCreate)alert('Soukromý repozitář je dostupný, ale cloudová databáze neexistuje. Klikněte „Vytvořit první cloudovou databázi“.');
  else if(result.conflict)alert('Konflikt dat: místní změny byly zachovány. Prohlédněte si stav v Cloud a zálohy.');
  else if(result.ready){form.querySelector('[name=token]').value='';render();}
 }catch(err){alert('GitHub Cloud: '+err.message)}
 finally{if(btn)btn.disabled=false;const box=document.querySelector('[data-cloud-status]');if(box)box.textContent=cloudStatusLabel()+(cloudSync.issue?' · '+cloudSync.issue:'');}
},true);
document.addEventListener('click',async e=>{
 const b=e.target.closest?.('[data-cloud-action]');if(!b)return;e.preventDefault();
 const action=b.dataset.cloudAction;
 try{
  if(action==='create'){
   const form=document.querySelector('#hmk-cloud-connect-form');
   const values=new FormData(form);const owner=String(values.get('owner')||'').trim(),repo=String(values.get('repo')||'').trim(),token=String(values.get('token')||'').trim();
   const rememberDevice=!!form.querySelector('[name=rememberDevice]')?.checked;
   if(!confirm('Zapsat tento místní stav postav a kampaní do soukromého repozitáře '+owner+'/'+repo+'? Pouze pokud tam cloudová databáze dosud neexistuje.'))return;
   const outcome=await cloudSync.connect({owner,repo,accessToken:token,createIfMissing:true,rememberDevice});
   if(outcome.ready)alert('Cloudové úložiště bylo vytvořeno. Otevřete stejný soukromý repozitář na druhém zařízení.');
  }
  if(action==='dev-reset'){
   b.disabled=true;
   try{await cloudSync.resetDevelopmentCampaign({emptySnapshot:JSON.stringify(clean())});}
   finally{b.disabled=false;}
  }
  if(action==='retry')await cloudSync.flush();
  if(action==='refresh')await cloudSync.refresh();
  if(action==='replace'){
   if(!confirm('POZOR: místní neodeslané změny budou nahrazeny verzí uloženou na GitHubu. Chcete opravdu pokračovat?'))return;
   await cloudSync.replaceWithCloud();
  }
  if(action==='remember'){
   await cloudSync.rememberCurrentDevice();
  }
  if(action==='forget'){
   if(!confirm('Odstranit trvale zapamatovaný GitHub token z tohoto zařízení? Aktuální připojení zůstane aktivní do konce relace.'))return;
   cloudSync.forgetDeviceToken();
  }
  if(action==='disconnect'){
   if(!confirm('Odpojit toto zařízení od cloudu? Další zápisy budou jen místní. Neodeslané změny se tím neodešlou.'))return;
   cloudSync.disconnect();
  }
  render();
 }catch(err){alert('GitHub Cloud: '+err.message);render()}
},true);
cloudSync.startup();
// F12 does not send a GitHub request. While this authenticated page remains
// alive, detect deletion of the cloud marker and issue an authorised reset.
// A wiped / reloaded browser without its token cannot do this retroactively.
let lastAutomaticCloudResetAttempt=0,automaticCloudResetRunning=false;
async function checkDeveloperStorageReset(){
 if(!cloudSync?.localStorageCleared||automaticCloudResetRunning)return;
 const now=Date.now();if(now-lastAutomaticCloudResetAttempt<15000)return;
 lastAutomaticCloudResetAttempt=now;automaticCloudResetRunning=true;
 try{await cloudSync.resetDevelopmentCampaign({emptySnapshot:JSON.stringify(clean())});}
 catch(err){const box=document.querySelector('[data-cloud-status]');if(box)box.textContent='F12: vymazání cloudu selhalo ('+err.message+'). Stránku zatím neobnovujte; reset bude zopakován.';console.error('HMK cloud reset after F12:',err);}
 finally{automaticCloudResetRunning=false;}
}
setInterval(()=>{void checkDeveloperStorageReset();},1000);
setInterval(()=>{if(document.visibilityState==='visible')void cloudSync.refresh();},30000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')void cloudSync.refresh()});
